/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A19: 80 frozen lemmas, written in four audited 20-word checkpoints. */
'use strict';
const D = globalThis.RA.D;
const E = (origin, word) => ({origin, prefix:null, root:null, suffix:null, source:'Etymonline, https://www.etymonline.com/word/'+word.toLowerCase()});
const C = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M = (wrong,right,reason,errorType='meaning') => ({wrong,right,reason,errorType});
const Q = (w,n,sense,prompt,options,answer,explain,errorType='meaning') => ({id:w+'.q'+n,senseId:w+'.s'+sense,errorType,type:'辨义与用法',prompt,options,answer,explain});
D('continually',{etymology:E('continual 加副词后缀 -ly；continual 经古法语 continual 来自拉丁语 continuus“连续的”。continually 常指反复发生，可能有间歇。','continually'),contexts:[C('continually.s1','电话服务','The alarm rang continually through the night, stopping for a few seconds before starting again each time the sensor detected movement.','警报整夜反复响起，每次传感器检测到动静后会响一阵、停几秒再响。','The alarm rang continually through the night / stopping for a few seconds / before starting again each time the sensor detected movement.','continually 修饰 rang，表示有间隔地反复发生。','警报多次响起且间有停顿，符合反复出现义 s1。')],mistakes:[M('The monitor ran continually for twelve hours without a single pause, and the engineer used continually to stress the uninterrupted operation.','The monitor ran continuously for twelve hours without a single pause, and the engineer used continuously to stress the uninterrupted operation.','明确无停顿应选 continuously；continually 更常说反复发生，可能有间歇。','confusable')],quiz:[Q('continually',1,1,'A phone that rings, pauses, and rings again is ringing ___.',['continually','annually','silently'],'continually','continually often describes repeated events separated by short breaks.'),Q('continually',2,2,'Which sentence best shows the frequency sense of continually?',['She continually checks the forecast several times a day.','The light remained continuously on with no break.','The office opens once each winter.'],'She continually checks the forecast several times a day.','Repeated checks show high frequency over a period.'),Q('continually',3,1,'The beeping stopped briefly after each alert, then returned. How did it sound?',['continually','once','permanently without a pause'],'continually','Brief pauses between repeated beeps fit continually.'),Q('continually',4,1,'In “continually revised,” the adverb most strongly suggests?',['revised again and again','revised only once','revised with no possible interruption'],'revised again and again','The word foregrounds recurrence; continuously would emphasize an unbroken process.') ]});
D('continuation',{etymology:E('continuation is formed from continue (Old French continuer, Latin continuare “join together”) plus the noun-forming suffix -ation.','continuation'),contexts:[C('continuation.s2','小说出版','The publisher released a continuation of the novel, picking up the characters’ story several years after the original final chapter.','出版社推出了这部小说的续篇，从原作最后一章数年后继续讲述人物的故事。','The publisher released a continuation of the novel / picking up the characters’ story / several years after the original final chapter.','a continuation of 后接被延续的作品；现在分词短语说明续篇的内容。','故事在原作结尾之后继续，符合续篇义 s2。')],mistakes:[M('The publisher called a completely unrelated collection of recipes a continuation of the novel, although it carried none of the story forward.','The publisher called a follow-up volume featuring the same characters a continuation of the novel.','续篇必须延展原作品的故事或过程；无关食谱不符合该义。')],quiz:[Q('continuation',1,2,'A continuation of a story normally?',['takes up and extends what came before','replaces every earlier event with unrelated recipes','ends before the original story begins'],'takes up and extends what came before','A continuation carries an existing narrative or process forward.'),Q('continuation',2,1,'The meeting’s continuation after lunch means?',['the meeting resumes after a pause','the meeting is canceled forever','a new building is constructed'],'the meeting resumes after a pause','Continuation can mean that an activity starts again after stopping.'),Q('continuation',3,2,'Which item is a likely continuation of a novel?',['a sequel following its characters','a cookbook with unrelated recipes','a dictionary’s index'],'a sequel following its characters','A sequel extends the earlier story.'),Q('continuation',4,1,'Choose the natural phrase.',['a continuation of the investigation','a continuation of the investigation that abandons it entirely','a continuation between two unrelated planets'],'a continuation of the investigation','The noun commonly takes of to name the activity being continued.') ]});
D('continuator',{etymology:E('continuator is built from continue, ultimately Latin continuare “join or make continuous,” and the agent suffix -ator; the rare noun names one who carries something on.','continuator'),contexts:[C('continuator.s1','学术编纂','After the historian died, her former student served as continuator, finishing the chronicle in the same careful style and documenting where the new chapters began.','历史学家去世后，她的昔日学生担任续作者，以同样谨慎的风格完成编年史，并标明新章节的起点。','After the historian died / her former student served as continuator / finishing the chronicle in the same careful style / and documenting where the new chapters began.','serve as 后接身份名词；现在分词短语说明续作者做了什么。','学生接续已故学者未完成的编年史，是作品或传统的续作者。')],mistakes:[M('The continuator discarded the unfinished chronicle and wrote an unrelated cookbook instead.','The continuator completed the unfinished chronicle in keeping with the earlier work.','continuator 指延续他人作品或传统的人；放弃原作另写无关内容不符合定义。')],quiz:[Q('continuator',1,1,'A continuator of a chronicle is someone who?',['carries the work on after another writer','translates every word into a new alphabet','destroys the records before reading them'],'carries the work on after another writer','The rare agent noun denotes a person who continues an existing work or tradition.'),Q('continuator',2,1,'An editor calls a student the continuator of a mentor’s unfinished book. What did the student do?',['finished or extended the book','wrote a wholly unrelated menu','only printed the title page'],'finished or extended the book','The role is to carry forward work begun by someone else.'),Q('continuator',3,1,'Which person best fits continuator?',['a successor who preserves and extends a tradition','a visitor who attends one lecture','a critic who refuses to discuss the work'],'a successor who preserves and extends a tradition','A continuator takes up and carries on an earlier work or tradition.'),Q('continuator',4,1,'The suffix -ator here helps name?',['a person performing the act of continuing','a place where books are stored','the past tense of continue'],'a person performing the act of continuing','-ator forms an agent noun in this word.') ]});
D('continuity',{etymology:E('continuity came through French continuite from Latin continuus “uninterrupted, connected”; the suffix -ity forms a noun for a state or quality.','continuity'),contexts:[C('continuity.s2','影视制作','The editor checked continuity between the two shots: the cup was full in the first frame and suddenly empty in the next, though the scene showed no one touching it.','剪辑师检查两个镜头之间的连贯性：第一帧杯子是满的，下一帧却突然空了，而场景里无人碰过它。','The editor checked continuity between the two shots / the cup was full in the first frame / and suddenly empty in the next / though the scene showed no one touching it.','continuity between A and B 表示两者衔接一致；冒号引出不连贯的具体例子。','道具状态无缘由地改变，破坏剧情/画面的前后一致，符合 s2。')],mistakes:[M('The film had perfect continuity: a character’s coat changed colour between adjacent frames for no explained reason.','The film had a continuity error: a character’s coat changed colour between adjacent frames for no explained reason.','相邻镜头无解释的服装变化是连贯性错误，不是“完美连贯”。')],quiz:[Q('continuity',1,2,'A film continuity check is most likely to catch?',['a glass that changes from full to empty between shots','the actor’s correct pronunciation','the ticket price at the cinema'],'a glass that changes from full to empty between shots','Continuity in film concerns consistency from one shot or scene to another.'),Q('continuity',2,1,'Continuity of electricity means the supply?',['does not keep being interrupted','changes its voltage at random every second','is available only once a year'],'does not keep being interrupted','The basic sense is an ongoing, connected state.'),Q('continuity',3,2,'The timeline has continuity when?',['events connect coherently across the story','every chapter contradicts the previous one','the final page is missing'],'events connect coherently across the story','A coherent link among story parts is the narrative sense.'),Q('continuity',4,1,'Which is a continuity error?',['a character holds a hat in one shot and it vanishes in the next','a scene uses a new camera angle','an actor speaks clearly'],'a character holds a hat in one shot and it vanishes in the next','An unexplained change across shots breaks continuity.') ]});
D('continuously',{etymology:E('continuously is continuous plus -ly; continuous came through French from Latin continuus, related to continuare “join together.”','continuously'),contexts:[C('continuously.s1','水质监测','A sensor continuously measured the river’s oxygen level for twenty-four hours, transmitting a reading every second without being switched off.','传感器连续二十四小时测量河流含氧量，每秒传回一次读数，期间从未关闭。','A sensor continuously measured the river’s oxygen level for twenty-four hours / transmitting a reading every second / without being switched off.','continuously 修饰 measured，强调整个时段无中断；without being switched off 作补充。','设备保持开启并不断测量，符合不间断义。')],mistakes:[M('The pump stopped every ten minutes for a long rest, yet the report says it operated continuously all afternoon.','The pump operated intermittently all afternoon, stopping every ten minutes for a long rest.','反复停机不符合 continuously 所强调的连续、不间断。','confusable')],quiz:[Q('continuously',1,1,'A machine runs continuously for an hour. What happens during that hour?',['It does not stop.','It starts once every few weeks.','It is used only at lunchtime.'],'It does not stop.','Continuously means without interruption during the stated period.'),Q('continuously',2,1,'Which adverb fits a stream flowing without a break?',['continuously','continually with long pauses','occasionally'],'continuously','An unbroken flow is continuous.'),Q('continuously',3,1,'The recorder stayed on and captured sound every second. It recorded?',['continuously','sporadically','once only'],'continuously','Recording at every moment without stopping fits the adverb.'),Q('continuously',4,1,'Compared with continually, continuously emphasizes?',['an unbroken process','separate repetitions with gaps','a predictable annual event'],'an unbroken process','Continuously foregrounds absence of a break.') ]});
D('continuum',{etymology:E('continuum is a Latin loan from continuus “continuous”; English uses the neuter Latin form for an unbroken range, and mathematics for a continuous set of points.','continuum'),contexts:[C('continuum.s1','教育评估','Rather than placing every learner in a strict beginner or advanced box, the school described proficiency as a continuum with many gradual levels between the two ends.','学校没有把每位学习者硬分成初级或高级，而是把熟练度描述为一个连续体，两端之间还有许多渐进层级。','Rather than placing every learner in a strict beginner or advanced box / the school described proficiency as a continuum / with many gradual levels between the two ends.','a continuum with levels 表示两端之间渐变的一系列程度。','熟练度不是截然分组，而是在中间连续变化，符合 s1。')],mistakes:[M('The scale is a continuum with only two isolated points and no intermediate positions.','The scale has two isolated categories rather than a continuum, because it offers no intermediate positions.','有许多渐变位置才构成 continuum；只有互不相连的两点不是连续体。')],quiz:[Q('continuum',1,1,'A language-skill continuum contains?',['gradual levels between its endpoints','only two unrelated choices with no middle','a list of alphabetized surnames'],'gradual levels between its endpoints','A continuum is a range with no sharp breaks.'),Q('continuum',2,2,'In mathematics, a continuum may refer to?',['an unbroken set of points','a single isolated dot only','a discontinuous set with large gaps'],'an unbroken set of points','The mathematical use describes continuous points or magnitude.'),Q('continuum',3,1,'The phrase “a continuum from informal to formal” suggests?',['degrees of formality between the ends','exactly one permitted style','two styles that never overlap'],'degrees of formality between the ends','The word presents intermediate gradations, not a simple either/or.'),Q('continuum',4,1,'Which description contradicts continuum?',['separate categories with no intermediate values','a range changing by small degrees','an unbroken progression'],'separate categories with no intermediate values','A continuum has gradation rather than a hard gap.') ]});
D('contort',{etymology:E('contort came from Latin contorquere “twist together,” from con- “together” and torquere “to twist”; English uses it for an unnatural twisted shape.','contort'),contexts:[C('contort.s1','疼痛反应','When the splinter entered his palm, the child’s face contorted with pain, but he held still while the nurse removed it.','木刺扎进手掌时，孩子疼得脸都扭曲了，但他在护士取刺时仍忍住没动。','When the splinter entered his palm / the child’s face contorted with pain / but he held still / while the nurse removed it.','face contorted with pain 是常见搭配；while 从句交代同时发生的动作。','面部因疼痛呈不自然扭曲，正是动词义。')],mistakes:[M('The metal rod remained perfectly straight after the workers contorted it into a tight spiral.','The metal rod became a tight spiral after the workers contorted it.','contort 表示扭成不自然的形状；若仍笔直就没有发生扭曲。')],quiz:[Q('contort',1,1,'If pain makes someone’s face contort, the face?',['twists into an unnatural expression','becomes perfectly still and unchanged','turns into a written document'],'twists into an unnatural expression','Contort describes twisting the face or body into a distorted shape.'),Q('contort',2,1,'A flexible wire is contorted into a loop. What happened?',['It was twisted into a new shape.','It was polished without bending.','It was cut into powder.'],'It was twisted into a new shape.','To contort an object is to twist it out of its normal shape.'),Q('contort',3,1,'Which action could contort a metal strip?',['bending and twisting it sharply','weighing it on a scale','painting it while it stays straight'],'bending and twisting it sharply','The verb entails twisting or distorting shape.'),Q('contort',4,1,'Choose the natural sentence.',['His features contorted as the bitter medicine hit his tongue.','His features contorted because they stayed in their usual relaxed shape.','He contorted a calendar by reading it aloud.'],'His features contorted as the bitter medicine hit his tongue.','An involuntary grimace is a natural use of the verb.') ]});
D('contraction',{etymology:E('contraction came through French contraction from Latin contractio, from contrahere “draw together”; in grammar it names a shortened form such as do not → don’t.','contraction'),contexts:[C('contraction.s2','语法教学','In the dialogue, the teacher circled the contraction “we’re” and asked students to expand it to “we are” before discussing the speaker’s informal tone.','在对话中，老师圈出缩写式 we’re，让学生先把它展开为 we are，再讨论说话者较随意的语气。','In the dialogue / the teacher circled the contraction “we’re” / and asked students to expand it to “we are” / before discussing the speaker’s informal tone.','contraction 后面的 we’re 是缩合形式；expand it to 表示展开为完整形式。','we’re 是 we are 的缩写，属于语法义 s2。')],mistakes:[M('The editor expanded the contraction “they’re” to “they are,” calling it an example of shortening.','The editor expanded the contraction “they’re” to “they are,” reversing the shortening.','they’re 到 they are 是展开，不是缩短；不能据此称为 shortening。','grammar')],quiz:[Q('contraction',1,2,'Which is a contraction of they are?',['they’re','their','there'],'they’re','They’re combines they and are in a shortened written form.'),Q('contraction',2,1,'A doctor describes a muscle contraction. What is contracting?',['the muscle is tightening or shortening','two words are being joined by an apostrophe','a letter is being mailed'],'the muscle is tightening or shortening','The bodily sense is a muscle’s tightening or shortening.'),Q('contraction',3,2,'Which pair shows a grammatical contraction?',['cannot → can’t','large → larger','walk → walked'],'cannot → can’t','Can’t is the contracted form of cannot.'),Q('contraction',4,1,'In grammar, “I’ve” is a contraction because it?',['shortens I have','makes I plural','changes have into a noun'],'shortens I have','I’ve combines I and have in shortened form.') ]});
D('contractor',{etymology:E('contractor is contract plus agent suffix -or; contract came through French from Latin contractus, the past participle of contrahere “draw together, make an agreement.”','contractor'),contexts:[C('contractor.s1','房屋维修','The city hired a licensed contractor to replace the library roof for a fixed price, and the firm supplied its own workers and materials.','市政府聘请有执照的承包商，以固定价格更换图书馆屋顶；该公司自行提供工人和材料。','The city hired a licensed contractor / to replace the library roof for a fixed price / and the firm supplied its own workers and materials.','contractor 是 hired 的宾语；to replace 说明合同工作内容。','企业承接固定价格的工程，符合承包商义 s1。')],mistakes:[M('The contractor promised to rebuild the roof under a signed work agreement, but claimed that a contractor can never be paid for a project.','The contractor promised to rebuild the roof under a signed work agreement and submitted an invoice for the completed work.','承包商受聘履约并按合同收款；“绝不能获酬”与职位含义冲突。')],quiz:[Q('contractor',1,1,'A building contractor is hired to?',['carry out agreed construction work','inspect grammar in a poem','lend books at a library'],'carry out agreed construction work','A contractor undertakes work under an agreement, often for a set price.'),Q('contractor',2,2,'Which person is a contractor in the legal sense?',['a party bound by the signed agreement','a passerby who never joined the agreement','a witness who only watched the signing'],'a party bound by the signed agreement','The legal sense can name a person who enters a contract.'),Q('contractor',3,1,'A homeowner pays a contractor after a renovation. The contractor most likely?',['performed the contracted work','sold the homeowner a novel','issued a weather report'],'performed the contracted work','The ordinary occupational use refers to a person or firm hired to do work.'),Q('contractor',4,1,'Which detail points to a contractor rather than an employee?',['a firm agrees to complete a defined project for a price','a worker receives only a library card','a visitor signs no work agreement'],'a firm agrees to complete a defined project for a price','Contractors commonly take on specified work under contract.') ]});
D('contradictory',{etymology:E('contradictory is formed from contradict plus -ory; contradict comes from Latin contradicere, contra “against” + dicere “say.”','contradictory'),contexts:[C('contradictory.s1','证词核对','The two witnesses gave contradictory accounts: one placed the van at the station at noon, while the other said it was across town at the same time.','两名证人给出了相互矛盾的说法：一人说货车中午在车站，另一人却称同一时间它在城镇另一端。','The two witnesses gave contradictory accounts / one placed the van at the station at noon / while the other said it was across town at the same time.','contradictory 修饰 accounts；while 对照两项不能同时成立的陈述。','对同一时刻地点给出排斥的说法，符合相互矛盾义 s1。')],mistakes:[M('The two reports were contradictory because both said the bridge opened at nine and neither made any conflicting claim.','The two reports agreed that the bridge opened at nine, so their accounts were consistent rather than contradictory.','完全相同且不冲突的陈述彼此一致，不能称为 contradictory。')],quiz:[Q('contradictory',1,1,'Two claims are contradictory when?',['they cannot both be true in the same circumstances','they express the same fact in different fonts','one gives a date and the other gives an unrelated color'],'they cannot both be true in the same circumstances','Contradictory statements oppose one another.'),Q('contradictory',2,2,'Which pair is contradictory?',['“The room is empty” and “Three people are inside it.”','“The room is large” and “It has a high ceiling.”','“The room is blue” and “The door is open.”'],'“The room is empty” and “Three people are inside it.”','The first pair cannot both describe the same room at the same time.'),Q('contradictory',3,1,'A witness says the car was red; another says it was green. Their accounts are?',['contradictory','identical','alphabetical'],'contradictory','They make incompatible claims about the car’s color.'),Q('contradictory',4,2,'A contradictory element in a plan is one that?',['directly conflicts with another part','supports every other part','has no relation to anything in the plan'],'directly conflicts with another part','The noun sense names something that opposes another.') ]});
D('contrariety',{etymology:E('contrariety is built on contrary, from Old French contraire and Latin contrarius “opposite,” with the abstract noun ending -ety.','contrariety'),contexts:[C('contrariety.s1','哲学讨论','The lecturer used the contrariety between duty and desire to show why the character could not satisfy both demands at once.','讲师借职责与欲望之间的对立，说明人物为何无法同时满足两种要求。','The lecturer used the contrariety between duty and desire / to show why the character could not satisfy both demands at once.','contrariety between A and B 表示 A 与 B 的对立；to show 引出论证目的。','职责与欲望相互冲突，体现抽象名词的对立义。')],mistakes:[M('There was no contrariety between the two policies: both required exactly the same action in the same case.','There was agreement rather than contrariety between the two policies: both required the same action.','内容一致是相合而非对立；contrariety 指相反或冲突关系。')],quiz:[Q('contrariety',1,1,'Contrariety between two positions means?',['opposition between them','their exact agreement','their shared spelling'],'opposition between them','The noun denotes opposition or the quality of being contrary.'),Q('contrariety',2,1,'A debate about freedom and strict control may explore their?',['contrariety','continuity','conveyance'],'contrariety','These ideas can stand in opposition.'),Q('contrariety',3,1,'Which situation best illustrates contrariety?',['two rules require opposite actions in one case','two labels name the same object','two clocks show the same time'],'two rules require opposite actions in one case','Incompatible requirements demonstrate opposition.'),Q('contrariety',4,1,'Choose the nearest meaning of contrariety.',['opposition','courtesy','transport'],'opposition','Contrariety is the state or relation of being contrary.') ]});
D('contravene',{etymology:E('contravene is a back-formation from contravention and ultimately Latin contravenire, contra “against” + venire “come.”','contravene'),contexts:[C('contravene.s1','建筑法规','The proposed balcony would contravene the fire code because it blocks the only emergency exit from the upper floor.','拟建阳台会违反消防规范，因为它堵住了上层唯一的紧急出口。','The proposed balcony would contravene the fire code / because it blocks the only emergency exit from the upper floor.','contravene 后接被违反的规则；because 从句说明违规原因。','设计与消防规范相抵触，属于违反规则义 s1。')],mistakes:[M('The contractor contravened the safety rule by following every required precaution, so the inspector cited him for compliance.','The contractor complied with the safety rule by following every required precaution, so the inspector recorded his compliance.','遵守规则应说 comply with；contravene 意为违反。','confusable')],quiz:[Q('contravene',1,1,'To contravene a regulation is to?',['break or conflict with it','follow it exactly','write it in a different font'],'break or conflict with it','The verb means to violate a rule, law, or agreement.'),Q('contravene',2,1,'A design that blocks a required fire exit would?',['contravene the fire code','comply with the fire code','translate the fire code'],'contravene the fire code','The design conflicts with the regulation.'),Q('contravene',3,2,'A new finding may contravene an earlier claim if it?',['conflicts with that claim','copies its punctuation','supports it in every detail'],'conflicts with that claim','The verb can also mean to conflict with a statement.'),Q('contravene',4,1,'Choose the correct completion: “The action may contravene ___.”',['the treaty','obediently','a permission to follow it'],'the treaty','A treaty is an agreement that an action can violate.') ]});
D('contributor',{etymology:E('contributor comes from contribute, through French from Latin contribuere “bring together or add,” plus agent suffix -or.','contributor'),contexts:[C('contributor.s2','杂志编辑','The magazine thanked each contributor by name, including the local historian who submitted a short article about the harbor’s changing shoreline.','杂志逐一向投稿人致谢，其中包括提交港口海岸线变迁短文的当地历史学家。','The magazine thanked each contributor by name / including the local historian / who submitted a short article / about the harbor’s changing shoreline.','contributor 可由 by name 指明；who 从句说明此人向刊物投稿。','提交文章给杂志的人是投稿人义 s2。')],mistakes:[M('The newspaper listed a contributor who had never sent it any writing, photographs, or other material.','The newspaper listed a subscriber who had never sent it any writing, photographs, or other material.','未提供内容的人不是投稿者；contributor 的相关义要求作出贡献/投稿。')],quiz:[Q('contributor',1,2,'A contributor to a magazine is someone who?',['writes or supplies material for it','subscribes only to its mailing list','prints the paper at a factory'],'writes or supplies material for it','The publishing sense is a person who contributes an article or other material.'),Q('contributor',2,1,'A contributor to a relief fund gives?',['money, time, or effort','a legal ban on the fund','only criticism and no help'],'money, time, or effort','Contributor also means someone who gives to a cause.'),Q('contributor',3,2,'The byline credits a contributor. That person most likely?',['submitted the article','delivered the newspaper route','designed the building across the street'],'submitted the article','A contributor can be an author of material in a publication.'),Q('contributor',4,1,'Which example uses contributor in the charity sense?',['Each contributor donated blankets to the shelter.','Each contributor edited the newspaper’s punctuation.','Each contributor refused to assist the shelter.'],'Each contributor donated blankets to the shelter.','Donating goods is giving support to a cause.') ]});
D('contributory',{etymology:E('contributory is formed from contribute (Latin contribuere, “bring together”) plus adjective suffix -ory; it describes something helping to cause a result or involving contributions.','contributory'),contexts:[C('contributory.s1','事故调查','Investigators found that poor lighting was a contributory factor in the crash, although the driver’s excessive speed remained the main cause.','调查人员认定照明不足是事故的促成因素之一，不过司机超速仍是主要原因。','Investigators found that poor lighting was a contributory factor in the crash / although the driver’s excessive speed remained the main cause.','a contributory factor 表示促成某结果的因素；although 区分次要与主要原因。','照明不足对事故有影响但非主因，符合促成作用义。')],mistakes:[M('The report called the broken brake contributory, while claiming it had no role at all in causing the collision.','The report called the broken brake contributory because it helped cause the collision.','若因素毫无作用，就不能称为 contributory；该词表示有助于造成结果。')],quiz:[Q('contributory',1,1,'A contributory factor in a delay?',['helps bring the delay about','has no possible connection to it','is always the only cause'],'helps bring the delay about','Contributory means helping to produce a result, not necessarily being its sole cause.'),Q('contributory',2,1,'If fatigue is contributory to an error, fatigue?',['played some part in causing it','proved the error impossible','was recorded after the error but unrelated'],'played some part in causing it','The adjective signals a contributing role.'),Q('contributory',3,1,'Which sentence uses contributory naturally?',['A lack of sleep was a contributory factor in the mistake.','The contributory factor had no link to the outcome whatsoever.','She contributory the report yesterday.'],'A lack of sleep was a contributory factor in the mistake.','The common construction is contributory factor in/to an outcome.'),Q('contributory',4,2,'A contributory pension scheme requires workers to?',['pay into the fund','avoid making any payment','contribute only after retirement ends'],'pay into the fund','In financial usage, contributory can describe a scheme funded by payments.') ]});
D('contrite',{etymology:E('contrite came through Old French from Latin contritus, literally “worn down,” past participle of conterere “grind”; the moral sense is humbled by remorse.','contrite'),contexts:[C('contrite.s2','工作失误','Her contrite apology named the confidential file she had sent to the wrong client and promised to notify the security team immediately.','她悔罪的道歉明确说出误发给错误客户的机密文件，并承诺立即通知安全团队。','Her contrite apology named the confidential file / she had sent to the wrong client / and promised to notify the security team immediately.','contrite 修饰 apology；过去完成时 had sent 表示道歉前的失误。','道歉显示真心悔过并打算弥补，体现 s2。')],mistakes:[M('He gave a contrite apology but laughed at the victim and refused to admit that his prank had caused harm.','He gave a mocking apology, laughed at the victim, and refused to admit that his prank had caused harm.','嘲笑受害者且拒绝认错并不表示真诚懊悔；contrite 与这种态度矛盾。')],quiz:[Q('contrite',1,1,'A contrite person feels?',['sincere sorrow for a wrong','pride in causing harm','indifference to every consequence'],'sincere sorrow for a wrong','Contrite describes genuine remorse.'),Q('contrite',2,2,'Which apology sounds contrite?',['“I was wrong; I will repair the damage and make sure it does not happen again.”','“I did nothing wrong, and I would do it again.”','“Your loss is amusing.”'],'“I was wrong; I will repair the damage and make sure it does not happen again.”','Acknowledging fault and trying to make amends shows remorse.'),Q('contrite',3,1,'A contrite expression after a serious mistake is likely?',['remorseful','triumphant','carefree'],'remorseful','The adjective conveys sorrow over one’s fault.'),Q('contrite',4,2,'Which detail is least compatible with being contrite?',['mocking the person harmed','admitting the harm','offering to make amends'],'mocking the person harmed','Mockery conflicts with sincere regret.') ]});
D('contrived',{etymology:E('contrived is the past participle of contrive, which came through Old French contreuver, from Latin contra “against” plus a verb of finding or devising; the modern adjective can imply artificial design.','contrived'),contexts:[C('contrived.s1','小说评论','The detective’s sudden discovery of a perfect clue felt contrived, because the clue appeared only when the plot had no other way to identify the culprit.','侦探突然发现完美线索显得牵强，因为只有在剧情找不到别的办法锁定凶手时，这条线索才出现。','The detective’s sudden discovery of a perfect clue felt contrived / because the clue appeared only when the plot had no other way / to identify the culprit.','felt contrived 表示看起来做作牵强；because 从句给出人工安排的理由。','线索只为解决剧情难题而突现，缺乏自然铺垫，符合该义。')],mistakes:[M('The dialogue felt contrived because it arose naturally from the characters’ established motives and sounded spontaneous.','The dialogue felt natural because it arose from the characters’ established motives and sounded spontaneous.','自然且符合人物动机的对白不是 contrived；该词暗示人为设计、缺少真实感。')],quiz:[Q('contrived',1,1,'A contrived plot twist often feels?',['artificially arranged','inevitable from well-laid clues','unplanned in every detail'],'artificially arranged','Contrived commonly criticizes something as unnatural or unconvincing.'),Q('contrived',2,1,'Which excuse sounds contrived?',['a sudden story invented to fit the facts after being caught','a consistent account supported by a time-stamped record','a clear explanation given before any dispute'],'a sudden story invented to fit the facts after being caught','It sounds devised for convenience rather than genuine.'),Q('contrived',3,1,'A naturally spoken line would least likely be called?',['contrived','spontaneous','unrehearsed'],'contrived','Contrived suggests artificiality, the opposite of spontaneous.'),Q('contrived',4,1,'The joke seemed contrived because it?',['was forced into the conversation and did not fit','arose naturally from the situation','made everyone laugh without explanation'],'was forced into the conversation and did not fit','A forced, unnatural construction fits the negative sense.') ]});
D('controllable',{etymology:E('controllable is formed from control, ultimately French contrôle, plus -able “capable of being”; it means capable of being kept within limits.','controllable'),contexts:[C('controllable.s1','野火防控','With the wind dropping and a firebreak already in place, the ranger judged the small hillside blaze controllable and kept the crew on standby.','风力减弱且隔离带已建好，护林员判断山坡上的小火势可控，并让队伍待命。','With the wind dropping and a firebreak already in place / the ranger judged the small hillside blaze controllable / and kept the crew on standby.','judge + object + adjective 表示判断某事物具有某性质。','火势可通过现有措施控制，没有失控扩大，符合词义。')],mistakes:[M('The leak was controllable, but no valve could stop it and water spread through every room.','The leak was uncontrollable: no valve could stop it and water spread through every room.','无法阻止且不断扩散的漏水应称 uncontrollable，不是 controllable。','word-formation')],quiz:[Q('controllable',1,1,'A controllable fire is one that?',['can be kept within limits','cannot be slowed or directed','has already burned every nearby building'],'can be kept within limits','The adjective means able to be controlled.'),Q('controllable',2,1,'Which situation is controllable?',['a small spill contained by closing a valve','a flood moving past every barrier','a machine whose controls are disconnected and ineffective'],'a small spill contained by closing a valve','The spill can be kept from spreading.'),Q('controllable',3,1,'The suffix -able in controllable contributes the sense?',['capable of being controlled','having controlled something in the past','a person who controls'],'capable of being controlled','-able commonly means capable of or suitable for the action.'),Q('controllable',4,1,'Choose the sentence that uses controllable correctly.',['The symptoms stayed controllable with a modest dose.','The symptoms were controllable, so no treatment could affect them.','She controllable the switch carefully.'],'The symptoms stayed controllable with a modest dose.','The symptoms could be kept within manageable limits.') ]});
D('controversial',{etymology:E('controversial derives from controversy, through Latin controversia “dispute,” from contra “against” and versus “turned”; the adjective describes something provoking disagreement.','controversial'),contexts:[C('controversial.s1','公共政策','The council postponed its controversial curfew proposal after residents argued that it would improve safety but unfairly restrict late-shift workers.','居民争论宵禁会提升安全却不公平地限制夜班工人后，市议会推迟了这项有争议的提案。','The council postponed its controversial curfew proposal / after residents argued that it would improve safety / but unfairly restrict late-shift workers.','controversial 修饰 proposal；but 对照支持理由和反对理由。','不同群体对政策利弊有公开分歧，符合引起争论义 s1。')],mistakes:[M('The council’s controversial rule was accepted without objection by every resident and caused no debate at all.','The council’s uncontroversial rule was accepted without objection by every resident and caused no debate at all.','无人反对且没有争论的规则不符合 controversial 的核心含义。')],quiz:[Q('controversial',1,1,'A controversial decision is likely to?',['provoke disagreement','receive no discussion or objection','describe a routine measurement only'],'provoke disagreement','Controversial means causing public disagreement or debate.'),Q('controversial',2,2,'A controversial public figure is one whose views?',['cause people to disagree strongly','are unknown to everyone','are accepted without question by all'],'cause people to disagree strongly','The adjective can describe a person who holds divisive opinions.'),Q('controversial',3,1,'Which topic is most likely to be called controversial?',['a policy that divides the community','a universally accepted spelling of Monday','a neutral list of library opening times'],'a policy that divides the community','Public disagreement makes a topic controversial.'),Q('controversial',4,1,'“The proposal remains controversial” implies?',['debate around it continues','all sides have reached agreement','the proposal is a kind of vehicle'],'debate around it continues','The statement signals unresolved disagreement.') ]});
D('controvert',{etymology:E('controvert came through French controverter from Latin controversus/controvertere, contra “against” + vertere “turn”; the verb means to dispute or refute.','controvert'),contexts:[C('controvert.s1','证据审查','The historian used shipping records to controvert the claim that the island had been uninhabited before the expedition arrived.','历史学家用航运记录反驳了“探险队抵达前该岛无人居住”的说法。','The historian used shipping records / to controvert the claim / that the island had been uninhabited / before the expedition arrived.','controvert the claim 表示对主张提出反驳；that 从句具体说明被反驳内容。','记录提供相反证据，用来驳斥一项论断。')],mistakes:[M('The researcher controverted the claim by presenting evidence that supported it in every detail.','The researcher corroborated the claim by presenting evidence that supported it in every detail.','完全支持主张是 corroborate；controvert 是反驳，两词不可互换。','confusable')],quiz:[Q('controvert',1,1,'To controvert a claim is to?',['argue that it is wrong','repeat it without comment','provide evidence that proves it correct'],'argue that it is wrong','Controvert means to dispute or refute a claim.'),Q('controvert',2,1,'Which action controverts a report?',['showing records that directly contradict its dates','copying its dates into a notebook','praising its clear formatting'],'showing records that directly contradict its dates','Conflicting evidence directly disputes the report.'),Q('controvert',3,1,'A witness controverted the allegation by?',['denying it and giving contrary evidence','confirming it with a signed statement','ignoring the courtroom entirely'],'denying it and giving contrary evidence','To controvert is to argue against a statement.'),Q('controvert',4,1,'Choose the correct contrast.',['corroborate supports a claim; controvert disputes it','both verbs mean to copy a claim','controvert means to recover from illness'],'corroborate supports a claim; controvert disputes it','The verbs point in opposite evidential directions.') ]});
D('convalesce',{etymology:E('convalesce came from Latin convalescere “begin to grow strong,” from con- “with” and valescere, “grow strong”; English retains the gradual recovery sense.','convalesce'),contexts:[C('convalesce.s1','术后休养','After the operation, Mira convalesced at her sister’s quiet home, taking short walks each day while the surgeon monitored her recovery.','手术后，米拉在姐姐安静的家里逐渐康复，每天散步一小会儿，同时由外科医生监测恢复情况。','After the operation / Mira convalesced at her sister’s quiet home / taking short walks each day / while the surgeon monitored her recovery.','convalesce 不及物，表示逐渐恢复健康；taking 短语说明恢复期的活动。','手术后逐步恢复体力，符合疾病后的康复义。')],mistakes:[M('The healthy athlete convalesced from a disease she had never had and recovered without being ill.','The healthy athlete trained for the race; a patient convalesces while recovering after illness.','convalesce 专指病后逐步康复，未生病者不能以此描述。')],quiz:[Q('convalesce',1,1,'A patient who convalesces is?',['gradually recovering after illness','beginning a new illness on purpose','performing surgery on a stranger'],'gradually recovering after illness','Convalesce means to regain health slowly after being ill.'),Q('convalesce',2,1,'After leaving hospital, he convalesced at home. What did he do?',['continued his recovery','started the operation','signed up as the surgeon'],'continued his recovery','Convalescence is the recovery period after illness.'),Q('convalesce',3,1,'Which person is most likely to convalesce?',['someone regaining strength after pneumonia','someone who has never been sick and is planning a picnic','someone delivering medicine as a courier'],'someone regaining strength after pneumonia','The verb specifically concerns post-illness recovery.'),Q('convalesce',4,1,'Choose the natural sentence.',['She convalesced for weeks before returning to work.','She convalesced the nurse into the room.','The healthy machine convalesced a battery.'],'She convalesced for weeks before returning to work.','Convalesce is generally intransitive and describes gradual recovery.') ]});
D('convection',{etymology:E('convection came from Latin convectio, from con- “together” and vehere “carry”; in science it names heat transfer by the movement of a fluid.','convection'),contexts:[C('convection.s1','室内供暖','The heater warms the air near the floor; that lighter air rises and cooler air sinks, setting up convection that gradually heats the whole room.','暖气加热靠近地面的空气；较轻的热空气上升，较冷的空气下沉，形成对流，逐渐使整个房间升温。','The heater warms the air near the floor / that lighter air rises and cooler air sinks / setting up convection / that gradually heats the whole room.','convection 指流体整体运动带来的热传递；that 从句修饰 convection。','空气冷热部分循环移动并传热，符合 s1。')],mistakes:[M('The solid, motionless metal rod transferred heat by convection from one end to the other.','The solid, motionless metal rod transferred heat by conduction from one end to the other.','热量沿静止固体传递属于 conduction；convection 依赖流体整体流动。','confusable')],quiz:[Q('convection',1,1,'In a room, convection transfers heat mainly by?',['movement of warmer and cooler air','light passing through a window','a solid metal rod vibrating in place'],'movement of warmer and cooler air','Convection involves flow in a liquid or gas.'),Q('convection',2,1,'Warm air rises while cooler air sinks. This circulation is?',['convection','contraction','corolla'],'convection','The moving fluid carries heat through the room.'),Q('convection',3,2,'Which material can carry heat by convection?',['flowing water','a stationary vacuum with no matter','a fixed color on a wall'],'flowing water','Convection occurs through moving liquids or gases.'),Q('convection',4,1,'A pot heats as hot water rises and cooler water descends. The process is?',['convection','translation','correlation'],'convection','Circulating water transports heat.') ]});
D('convenience',{etymology:E('convenience came through Old French from Latin convenientia “meeting, agreement,” from convenire “come together”; English developed the sense of suitability or ease.','convenience'),contexts:[C('convenience.s2','预约安排','Please choose a pickup time at your convenience; the parcel will remain at the desk until the end of the week.','请在方便的时候选择取件时间；包裹会在服务台保留到本周末。','Please choose a pickup time at your convenience / the parcel will remain at the desk / until the end of the week.','at your convenience 是礼貌表达，指对方方便的时候。','句子指适合收件人的时间，符合 s2。')],mistakes:[M('We scheduled the interview at the candidate’s convenience, choosing a time that the candidate said was impossible to attend.','We scheduled the interview at the candidate’s convenience, choosing a time the candidate had confirmed was suitable.','“在某人方便时”要求时间适合此人；明知无法参加就不便利。')],quiz:[Q('convenience',1,2,'“Call me at your convenience” means?',['call when the time suits you','call only when I am asleep','call at a time chosen to cause trouble'],'call when the time suits you','The phrase means at a suitable time for the person addressed.'),Q('convenience',2,1,'A self-checkout is a convenience because it?',['makes shopping easier','makes every purchase impossible','requires customers to write a formal letter'],'makes shopping easier','A convenience is something that makes life or a task easier.'),Q('convenience',3,2,'Which pickup plan is at the customer’s convenience?',['a slot the customer selected as suitable','a slot the customer cannot reach','a slot announced after the depot closes'],'a slot the customer selected as suitable','The time fits the customer’s schedule.'),Q('convenience',4,1,'“For your convenience” signals that a feature is intended to?',['save you trouble','delay you unnecessarily','replace the product’s main purpose'],'save you trouble','The phrase introduces an ease-enhancing feature.') ]});
D('conveniently',{etymology:E('conveniently is convenient plus adverb-forming -ly; convenient came from Latin convenient-, the stem of convenire “come together, be suitable.”','conveniently'),contexts:[C('conveniently.s2','新闻评论','Conveniently, the only surviving receipt was the one that supported the manager’s account, while every document that might challenge it had been discarded.','颇为“巧合”的是，唯一保存下来的收据恰好支持经理的说法，而所有可能质疑它的文件都已被丢弃。','Conveniently / the only surviving receipt was the one that supported the manager’s account / while every document that might challenge it had been discarded.','句首 Conveniently 表示事情恰好对某人有利；引号可提示讽刺语气。','证据恰好只剩有利的一份，带有“巧得可疑”的讽刺义 s2。')],mistakes:[M('The new desk is conveniently for storing the folded maps.','The new desk is convenient for storing the folded maps.','be 动词后要用形容词 convenient 作表语；conveniently 是副词。','grammar')],quiz:[Q('conveniently',1,1,'If a clinic is conveniently located near the station, it is?',['easy to reach','open only by appointment in another city','deliberately difficult to find'],'easy to reach','This is the ordinary sense of being suitably placed.'),Q('conveniently',2,2,'A suspect “conveniently forgot” the only relevant date. The wording may suggest?',['the forgetting seems suspiciously helpful','the date was printed in a large font','the suspect remembers every detail'],'the forgetting seems suspiciously helpful','The adverb can carry an ironic implication that events suit someone too well.'),Q('conveniently',3,1,'Which sentence uses the ironic sense?',['Conveniently, the sole witness had left before questioning began.','The bus stop is conveniently across from the clinic.','The form is conveniently printed in large type.'],'Conveniently, the sole witness had left before questioning began.','The timing appears suspiciously advantageous to someone.'),Q('conveniently',4,1,'A conveniently placed handle is?',['positioned where it is easy to use','hidden beyond the user’s reach','unrelated to the object'],'positioned where it is easy to use','The regular adverb sense describes useful placement.') ]});
D('conventionally',{etymology:E('conventionally derives from conventional plus -ly; conventional comes from convention, from Latin conventio “agreement or assembly,” and describes established custom.','conventionally'),contexts:[C('conventionally.s1','建筑设计','The old hall was conventionally heated by a central boiler, but the renovation added rooftop solar panels to reduce fuel use.','旧礼堂按传统方式由中央锅炉供暖，不过翻修时加装了屋顶太阳能板以减少燃料消耗。','The old hall was conventionally heated by a central boiler / but the renovation added rooftop solar panels / to reduce fuel use.','conventionally 修饰 heated，说明采用惯常方法；but 转折引出新方案。','中央锅炉是常规传统方式，与后文较新的太阳能改造相对。')],mistakes:[M('The building was conventionally heated by a newly invented method used nowhere else and never accepted as standard practice.','The building was unconventionally heated by a newly invented method used nowhere else and never accepted as standard practice.','从未被采纳的新发明方法不属于 conventional；应使用反义副词。','word-choice')],quiz:[Q('conventionally',1,1,'A conventionally dressed guest follows?',['usual accepted dress customs','a one-of-a-kind costume rule','no shared standard at all'],'usual accepted dress customs','Conventionally means in the customary or traditional way.'),Q('conventionally',2,1,'A house conventionally heated by gas uses?',['the usual established heating method','an untested device no one recognizes','no heating source'],'the usual established heating method','The adverb marks a common customary practice.'),Q('conventionally',3,1,'Which pair contrasts accurately?',['conventionally: by custom; innovatively: by a new method','conventionally: secretly; innovatively: yearly','conventionally: outdoors; innovatively: indoors'],'conventionally: by custom; innovatively: by a new method','The word contrasts established practice with innovation.'),Q('conventionally',4,1,'“The ceremony was conventionally held in spring” tells us it was held?',['according to the usual custom','for the first time ever','without any established pattern'],'according to the usual custom','Conventionally describes customary timing.') ]});
D('convergence',{etymology:E('convergence is converge plus noun suffix -ence; converge comes through French from Latin convergere, con- “together” + vergere “bend or turn.”','convergence'),contexts:[C('convergence.s1','媒体技术','The convergence of phones and cameras changed reporting: a journalist could record video, take still photographs, and send the story from one handheld device.','手机与相机功能的融合改变了新闻报道：记者可用一台手持设备拍视频、拍照片并发送报道。','The convergence of phones and cameras changed reporting / a journalist could record video / take still photographs / and send the story from one handheld device.','convergence of A and B 指两个领域趋于结合；冒号说明其结果。','多种设备功能汇集到一个设备中，体现趋同/汇聚 s1。')],mistakes:[M('The rivers showed convergence because they flowed farther apart and never approached the same valley.','The rivers showed divergence because they flowed farther apart and never approached the same valley.','彼此分开是 divergence；convergence 指趋向同一点或趋同。','confusable')],quiz:[Q('convergence',1,1,'The convergence of two roads means they?',['come toward and meet at a point','move farther apart forever','cross only in a dictionary'],'come toward and meet at a point','Convergence describes movement toward the same point.'),Q('convergence',2,2,'In computing, convergence may describe?',['formerly separate functions becoming combined','a device losing every shared feature','two systems moving to unrelated ends'],'formerly separate functions becoming combined','Separate technologies can converge as their functions combine.'),Q('convergence',3,1,'Which observation suggests convergence of opinions?',['people with different views grow more alike','the gap between their views steadily widens','no one states any view'],'people with different views grow more alike','The general sense includes growing similarity.'),Q('convergence',4,2,'When an algorithm approaches a stable limit, it shows?',['convergence','contrariety','conveyance'],'convergence','The mathematical sense is approaching a limit.') ]});
D('convergent',{etymology:E('convergent is formed from converge (Latin convergere, “incline together”) plus adjectival -ent; it describes things tending toward one point or limit.','convergent'),contexts:[C('convergent.s1','物种演化','The biologist described the streamlined bodies of sharks and dolphins as convergent adaptations, since unrelated lineages developed similar shapes in similar environments.','生物学家把鲨鱼和海豚的流线型体形称为趋同适应，因为不同谱系在相似环境中演化出相似形态。','The biologist described the streamlined bodies of sharks and dolphins as convergent adaptations / since unrelated lineages developed similar shapes / in similar environments.','convergent 修饰 adaptations；since 引出判断依据。','不同谱系朝类似形态发展，是趋同义。')],mistakes:[M('Two convergent paths began together and then moved steadily farther apart without meeting.','Two divergent paths began together and then moved steadily farther apart without meeting.','相互远离的路径是 divergent；convergent 表示向一点靠拢。','confusable')],quiz:[Q('convergent',1,1,'Convergent lines move?',['toward one another','steadily away from one another','in circles that never approach'],'toward one another','The adjective means tending toward the same point.'),Q('convergent',2,1,'A convergent series is one that?',['approaches a limit','grows without bound in every case','has no terms'],'approaches a limit','In mathematics, convergent describes approaching a finite limit.'),Q('convergent',3,1,'Unrelated species with similar adaptations may show?',['convergent evolution','convergent spelling','convergent postal delivery'],'convergent evolution','Separate evolutionary lines can independently develop similar traits.'),Q('convergent',4,1,'Choose the contrast.',['convergent rays meet; divergent rays spread apart','both terms mean parallel forever','convergent means moving backward in time'],'convergent rays meet; divergent rays spread apart','The words contrast movement toward versus away from a common point.') ]});
D('conversant',{etymology:E('conversant came from Latin conversant-, the present participle stem of conversari “associate or be familiar with”; English uses it with with to mean knowledgeable.','conversant'),contexts:[C('conversant.s1','软件采购','The procurement officer is conversant with open-source licensing, so she spotted that the vendor’s contract incorrectly prohibited redistribution.','采购专员熟悉开源许可，因此她发现供应商合同错误地禁止再分发。','The procurement officer is conversant with open-source licensing / so she spotted / that the vendor’s contract incorrectly prohibited redistribution.','be conversant with + 领域表示熟悉；so 引出知识带来的判断。','她能识别许可条款问题，说明对该领域相当熟悉。')],mistakes:[M('He is conversant with the new safety code, although he has never read it and cannot explain a single requirement.','He is unfamiliar with the new safety code, as he has never read it and cannot explain a single requirement.','从未读过且无法说明内容，不能称 conversant with。','word-choice')],quiz:[Q('conversant',1,1,'Someone conversant with tax law is?',['familiar enough with it to discuss it','unable to recognize any tax term','the person who writes a tax cheque'],'familiar enough with it to discuss it','Conversant means knowledgeable or familiar with a subject.'),Q('conversant',2,1,'Which construction is standard?',['conversant with the regulations','conversant on the regulations at','conversant the regulations'],'conversant with the regulations','The usual pattern is conversant with a topic.'),Q('conversant',3,1,'A guide conversant with local history can likely?',['answer informed questions about it','claim never to have heard of the town','replace every historical record'],'answer informed questions about it','Familiarity implies ability to talk knowledgeably.'),Q('conversant',4,1,'Pick the sentence matching conversant.',['The engineer is conversant with the revised standards.','The engineer is conversant because the standards are unreadable to her.','She conversant the machine after lunch.'],'The engineer is conversant with the revised standards.','The adjective takes with and describes familiarity.') ]});
D('conversational',{etymology:E('conversational is derived from conversation with adjective-forming -al; conversation passed through French from Latin conversari “keep company or associate.”','conversational'),contexts:[C('conversational.s1','口语课程','The teacher replaced the formal script with conversational English, asking pairs to plan a weekend trip using the phrases people actually say to friends.','老师把正式讲稿换成会话英语，让学生两人一组用人们和朋友实际交谈时会说的短语计划周末旅行。','The teacher replaced the formal script with conversational English / asking pairs to plan a weekend trip / using the phrases people actually say to friends.','conversational 修饰 English，指适用于日常交谈的表达；asking 短语说明课堂任务。','学生练习朋友间自然使用的口语，符合交谈用语义。')],mistakes:[M('The judge delivered a conversational sentence in dense legal language that nobody in the courtroom could follow.','The judge delivered a formal legal sentence in dense language that nobody in the courtroom could follow.','晦涩且正式的法律语言不符合面向日常交谈、自然易懂的 conversational。','register')],quiz:[Q('conversational',1,1,'Conversational English is language used?',['in ordinary speech and informal discussion','only in mathematical proofs','exclusively in ancient inscriptions'],'in ordinary speech and informal discussion','The adjective means used in or suitable for conversation.'),Q('conversational',2,1,'A conversational tone is usually?',['natural and talk-like','rigidly ceremonial','silent and written in code'],'natural and talk-like','A conversational style resembles ordinary conversation.'),Q('conversational',3,1,'Which phrase is conversational?',['“Could you give me a hand?”','“The undersigned hereby petitions the tribunal...”','a row of equations with no words'],'“Could you give me a hand?”','The first is an everyday spoken request.'),Q('conversational',4,1,'An interview described as conversational likely felt?',['like a relaxed exchange','like a courtroom verdict','like a wordless diagram'],'like a relaxed exchange','Conversational interaction resembles ordinary dialogue.') ]});
D('conversely',{etymology:E('conversely is formed from converse plus -ly; converse is from Latin conversus, past participle of convertere “turn around,” hence an opposite relation.','conversely'),contexts:[C('conversely.s2','逻辑推理','If every certified copy is signed, the converse is not automatically true; a signature alone does not prove that a document is certified.','如果每份认证副本都经过签署，反命题并不自动成立；仅有签名不能证明文件已经认证。','If every certified copy is signed / the converse is not automatically true / a signature alone does not prove / that a document is certified.','the converse 是“反过来的命题”；not automatically true 提醒逆命题需另行验证。','语境明确讨论命题反向后是否成立，符合逻辑义 s2。')],mistakes:[M('Every licensed pilot has passed the test, so conversely every person who passed any test must be a licensed pilot.','Every licensed pilot has passed the test, but the converse does not follow: passing a test alone does not establish a pilot’s license.','由 A→B 不能直接推出 B→A；conversely 不能掩盖逆命题的逻辑缺口。','meaning')],quiz:[Q('conversely',1,2,'In logic, the converse of “If A, then B” is?',['If B, then A.','If not A, then not B.','A and B are unrelated words.'],'If B, then A.','The converse reverses the order of condition and result.'),Q('conversely',2,1,'The first town grew richer; conversely, its neighbor grew poorer. Here conversely signals?',['the opposite situation','a supporting example with the same result','a cause that occurred earlier'],'the opposite situation','In general use it introduces an opposite or reversed case.'),Q('conversely',3,2,'“All squares are rectangles; conversely, not all rectangles are squares.” The word introduces?',['the reverse relation being considered','a new spelling rule','a time sequence'],'the reverse relation being considered','It marks the reverse direction of the claim.'),Q('conversely',4,1,'Choose a suitable transition: “The north slope is dry; ___, the south slope stays damp.”',['conversely','therefore','meanwhile, with no contrast'],'conversely','The sentence contrasts the opposite condition on the other slope.') ]});
D('conversion',{etymology:E('conversion came through Old French from Latin conversio, from convertere “turn around or transform,” con- “together” + vertere “turn.”','conversion'),contexts:[C('conversion.s2','宗教史','The historian found letters written after the merchant’s conversion to Buddhism, in which he explained why he had adopted the new faith.','历史学家发现了商人皈依佛教后写的信，他在信中解释了自己接受新信仰的原因。','The historian found letters written after the merchant’s conversion to Buddhism / in which he explained / why he had adopted the new faith.','conversion to + religion 表示改信；after 表明信件写于皈依之后。','从原信仰转而接受佛教，符合宗教皈依义 s2。')],mistakes:[M('Her conversion to Buddhism meant that she rejected the religion and adopted no new faith.','Her rejection of Buddhism meant that she left the religion and adopted no new faith.','conversion to 某宗教意味着接受该信仰；离开信仰应另表述。')],quiz:[Q('conversion',1,2,'A person’s conversion to a religion is?',['the adoption of that faith','the sale of a religious building','the translation of a hymn into another language'],'the adoption of that faith','The religious sense means changing to a different religion.'),Q('conversion',2,1,'Converting a file from PDF to text is a?',['change from one format to another','religious ceremony','movement from one room to the next'],'change from one format to another','Conversion broadly means changing something into another form.'),Q('conversion',3,1,'Which is a conversion in computing?',['changing an audio file into a different format','printing the same file twice without changes','deleting an unrelated folder'],'changing an audio file into a different format','The data format has been transformed.'),Q('conversion',4,2,'“His conversion to Islam” says that he?',['adopted Islam as his faith','left Islam without taking another faith','built a mosque for someone else'],'adopted Islam as his faith','The preposition to names the religion he adopted.') ]});
D('converter',{etymology:E('converter is formed from convert (Latin convertere “turn or transform”) plus agent/instrument suffix -er; it names a device or, in metallurgy, a furnace that converts material.','converter'),contexts:[C('converter.s2','钢铁生产','At the steelworks, molten iron entered a converter, where oxygen removed impurities and helped turn the iron into steel.','在钢厂，熔融铁水进入转炉，氧气在其中去除杂质并帮助把铁转化为钢。','At the steelworks / molten iron entered a converter / where oxygen removed impurities / and helped turn the iron into steel.','converter 指转炉设备；where 从句解释设备的冶炼作用。','铁水在炉中经吹氧转为钢，符合冶金义 s2。')],mistakes:[M('A steel converter changes molten iron into steel, while the operator calls the furnace a device for converting audio files.','A steel converter changes molten iron into steel; an audio converter changes one sound format into another.','炼钢转炉与数字格式转换器是不同设备，不可把用途混为一谈。','confusable')],quiz:[Q('converter',1,2,'In steelmaking, a converter is?',['a furnace used to turn molten iron into steel','a worker who sells steel tools','a belt that carries boxes'],'a furnace used to turn molten iron into steel','The metallurgical sense is a steelmaking furnace.'),Q('converter',2,1,'A USB converter is used to?',['change a signal or connection into another form','write a novel about a pilot','measure a plant’s petals'],'change a signal or connection into another form','A converter device changes one form of signal or data to another.'),Q('converter',3,1,'Which machine is a converter in the electronic sense?',['one that changes digital video to another format','a furnace that smelts iron only','a paper file cabinet'],'one that changes digital video to another format','It transforms the data representation.'),Q('converter',4,2,'Oxygen is blown through molten iron in a converter. This is?',['a steelmaking process','a language translation class','a transport service'],'a steelmaking process','The converter in this context is the steelmaking furnace.') ]});
D('convex',{etymology:E('convex came through French convexe from Latin convexus “vaulted or arched”; the adjective describes a surface curving outward.','convex'),contexts:[C('convex.s1','光学器材','A convex lens bulged outward on both sides, so the technician adjusted its distance from the screen until the projected image came into focus.','这枚凸透镜两侧都向外鼓起，因此技术员调整它与屏幕的距离，直到投影图像聚焦。','A convex lens bulged outward on both sides / so the technician adjusted its distance from the screen / until the projected image came into focus.','convex 修饰 lens；bulge outward 描述向外弯曲，until 引导结果时间界限。','镜片表面向外凸出，是形容词义 s1。')],mistakes:[M('The lens was convex, with both surfaces curving inward like the inside of a bowl.','The lens was concave, with both surfaces curving inward like the inside of a bowl.','向内弯的是 concave；convex 表示向外弯。','confusable')],quiz:[Q('convex',1,1,'A convex surface curves?',['outward','inward like a cave','only along a flat plane'],'outward','Convex describes a surface that bulges outward.'),Q('convex',2,2,'A convex mirror has which shape?',['its reflecting surface curves outward','its surface forms a deep inward bowl','it has no reflective surface'],'its reflecting surface curves outward','This is the outward-curving surface sense.'),Q('convex',3,1,'Which is the opposite of a convex lens?',['a concave lens','a cornet','a corolla'],'a concave lens','Concave curves inward, opposite to convex.'),Q('convex',4,1,'A dome-like lens is described as?',['convex','contrite','conversant'],'convex','The outward arch is convex.') ]});
D('conveyance',{etymology:E('conveyance derives from convey plus -ance; convey came through Old French from Latin conviare, “send or escort on a way.” English also uses conveyance in property law for transfer of title.','conveyance'),contexts:[C('conveyance.s2','不动产交易','The solicitor prepared the conveyance of the cottage to the buyer, recording the deed that transferred legal ownership at completion.','律师准备了小屋向买方的产权转让文件，记录交割时转移法定所有权的契据。','The solicitor prepared the conveyance of the cottage to the buyer / recording the deed / that transferred legal ownership at completion.','conveyance of property to a buyer 指财产所有权转移；that 从句修饰 deed。','所有权通过契据转给买方，符合法律转让义 s2。')],mistakes:[M('The conveyance of the cottage was complete, but the seller retained legal ownership and no deed transferred title.','The conveyance of the cottage was not complete, because the seller retained legal ownership and no deed transferred title.','没有契据、产权仍属卖方就没有完成产权转让。')],quiz:[Q('conveyance',1,2,'A legal conveyance of land is?',['the transfer of its ownership','a bus route past the land','a letter describing its color'],'the transfer of its ownership','In property law, conveyance means the legal transfer of title.'),Q('conveyance',2,1,'A conveyance used to take goods across town is?',['a means of transport','a property deed','a flower part'],'a means of transport','The ordinary noun can mean a vehicle or means of transport.'),Q('conveyance',3,2,'Which document records conveyance of a house?',['a deed transferring ownership','a recipe for dinner','a cinema ticket'],'a deed transferring ownership','A deed can effect the legal transfer.'),Q('conveyance',4,1,'In the sentence “Public conveyance was available,” conveyance means?',['transport for people','ownership in a building','a legal argument'],'transport for people','The broad transport sense refers to carrying people or goods.') ]});
D('conveyor',{etymology:E('conveyor comes from convey (Old French, ultimately Latin via “way”) plus agent suffix -or; it names a machine that carries objects and, less commonly, a person who conveys something.','conveyor'),contexts:[C('conveyor.s1','工厂装配','The boxes moved along a conveyor at waist height, and a sensor stopped the belt whenever a package reached the labeling station.','箱子沿腰部高度的传送带移动；包裹到达贴标工位时，传感器就会让皮带停下。','The boxes moved along a conveyor at waist height / and a sensor stopped the belt / whenever a package reached the labeling station.','conveyor 是 moved along 的载体；whenever 引导每次触发停机的情况。','皮带把箱子从一处送到另一处，符合机器义 s1。')],mistakes:[M('Workers carried each box by hand across the factory, and the supervisor called the empty stationary rail a working conveyor.','Workers carried each box by hand across the factory; no conveyor was moving the boxes.','静止且未运送物品的轨道不是正在工作的传送机。')],quiz:[Q('conveyor',1,1,'A conveyor in a factory is used to?',['carry items from one station to another','cool the room by burning fuel','record a worker’s biography'],'carry items from one station to another','A conveyor moves objects along a production line.'),Q('conveyor',2,1,'A conveyor belt stops when a box reaches the scanner. What is the belt doing?',['transporting boxes along a path','transferring property ownership','summoning a formal meeting'],'transporting boxes along a path','The machine conveys objects.'),Q('conveyor',3,2,'In legal language, a conveyor may be someone who?',['transfers property to another person','repairs a car engine','measures the curve of a lens'],'transfers property to another person','The less common sense names a person who conveys or transfers.'),Q('conveyor',4,1,'Which description fits a conveyor best?',['a moving mechanism carrying packages','a fixed sign with no moving parts','a person recovering from illness'],'a moving mechanism carrying packages','The usual machine sense involves transporting objects.') ]});
D('convinced',{etymology:E('convinced is the past participle of convince, from Latin convincere “overcome, prove,” con- “thoroughly” + vincere “conquer”; it describes being persuaded or certain.','convinced'),contexts:[C('convinced.s2','证据讨论','After comparing the timestamped footage with the witness’s account, the jury was convinced that the delivery van had arrived before the gate closed.','将带时间戳的录像与证人口供对照后，陪审团被说服，确信送货车是在大门关闭前抵达的。','After comparing the timestamped footage with the witness’s account / the jury was convinced / that the delivery van had arrived before the gate closed.','be convinced that + 从句表达确信某事实；after 从句交代依据。','证据改变判断，使陪审团确信，体现被说服义 s2。')],mistakes:[M('The jury was convinced by the footage, yet remained completely uncertain that the van had arrived at all.','The jury was unconvinced by the footage and remained uncertain whether the van had arrived.','若仍完全不确定，就不能说已被说服/确信。')],quiz:[Q('convinced',1,2,'A person convinced by the evidence has?',['been persuaded that it supports a conclusion','refused to consider the evidence','forgotten what evidence means'],'been persuaded that it supports a conclusion','Convinced can describe a changed belief caused by arguments or evidence.'),Q('convinced',2,1,'“I am convinced that the key is inside” means?',['I feel certain it is inside','I have no view about its location','I physically turned the key'],'I feel certain it is inside','Be convinced that expresses strong certainty.'),Q('convinced',3,1,'Which sentence uses the adjective correctly?',['She was convinced by the test results.','She convinced by the test results yesterday.','The test results were a convinced.'],'She was convinced by the test results.','The passive participle adjective commonly follows be.'),Q('convinced',4,2,'A lawyer convinced the client to appeal. The client was?',['persuaded to appeal','certain the case had no appeal','the person who wrote the law'],'persuaded to appeal','The verb caused the client to change their mind.') ]});
D('convincing',{etymology:E('convincing is the present participle adjective of convince, from Latin convincere “prove or overcome”; it can describe persuasive evidence or a strong, realistic appearance.','convincing'),contexts:[C('convincing.s2','影视道具','The foam rock looked convincing from the audience, although an actor could lift it with one hand during the scene.','从观众席看，这块泡沫岩石很逼真，尽管演员在戏中能单手把它举起来。','The foam rock looked convincing from the audience / although an actor could lift it with one hand / during the scene.','look convincing 表示看起来可信/逼真；although 引出实际道具很轻的反差。','道具外观足以让观众以为是真石头，符合“像真的”义 s2。')],mistakes:[M('The witness offered convincing proof, but every document directly disproved the claim and the witness admitted inventing it.','The witness offered unconvincing proof, since every document disproved the claim and the witness admitted inventing it.','证据被全部推翻且证人承认编造，不能称 convincing。','word-choice')],quiz:[Q('convincing',1,1,'A convincing explanation is one that?',['makes its conclusion seem believable','confuses every listener on purpose','contains no reason at all'],'makes its conclusion seem believable','Convincing means persuasive or capable of making someone believe.'),Q('convincing',2,2,'A convincing stage beard is?',['realistic-looking','made of steel and impossible to wear','an argument about a courtroom'],'realistic-looking','Convincing can mean having an appearance that seems real.'),Q('convincing',3,1,'Which evidence is most convincing?',['independent records that match the claim','an unsupported guess contradicted by every record','a blank sheet'],'independent records that match the claim','Relevant corroborating records strengthen belief.'),Q('convincing',4,1,'The actor gave a convincing performance. The audience thought it was?',['believable and effective','impossible to understand','a type of conveyance'],'believable and effective','A convincing performance persuades the audience of its reality.') ]});
D('convincingly',{etymology:E('convincingly is convincing plus adverbial -ly; convince descends from Latin convincere “overcome or prove,” and the adverb describes persuasive manner.','convincingly'),contexts:[C('convincingly.s1','庭审陈述','The analyst explained the pattern convincingly, showing the original measurements and answering questions about the one result that did not fit.','分析员有说服力地解释了这一模式，展示原始测量数据，并回答了关于那项不吻合结果的问题。','The analyst explained the pattern convincingly / showing the original measurements / and answering questions / about the one result that did not fit.','convincingly 修饰 explained，说明解释的说服效果；showing 与 answering 并列。','使用原始证据且正面处理反例，体现令人信服的方式。')],mistakes:[M('The speaker argued convincingly, giving no evidence, ignoring every objection, and leaving listeners entirely unconvinced.','The speaker argued unconvincingly, giving no evidence, ignoring every objection, and leaving listeners entirely unconvinced.','听众不信且论证无证据，不应称为 convincingly。','word-choice')],quiz:[Q('convincingly',1,1,'To argue convincingly is to argue?',['in a way that persuades others','without any attempt to support a point','in a voice no one can hear'],'in a way that persuades others','The adverb describes a manner that makes a claim believable.'),Q('convincingly',2,1,'She played the historical queen convincingly. This means she?',['made the portrayal seem believable','forgot every line and left the stage','proved the queen was present in the room'],'made the portrayal seem believable','The adverb applies to a realistic or persuasive performance.'),Q('convincingly',3,1,'Which presentation is delivered convincingly?',['one supported by clear evidence and a coherent reply','one contradicted by its own data','one with no stated conclusion'],'one supported by clear evidence and a coherent reply','Relevant support and coherence help persuade.'),Q('convincingly',4,1,'Choose the correct completion: “The experiment ___ ruled out contamination.”',['convincingly','convincing','convince'],'convincingly','An adverb modifies the verb ruled out.') ]});
D('convivial',{etymology:E('convivial came through French from Latin convivialis, from convivium “feast,” related to convivere “live or eat together”; it describes friendly social enjoyment.','convivial'),contexts:[C('convivial.s1','社区晚宴','The neighborhood held a convivial supper in the courtyard, where new residents met longtime neighbors over shared dishes and live music.','街坊在院子里办了一场欢乐友好的晚餐会，新住户一边分享菜肴、听现场音乐，一边认识老邻居。','The neighborhood held a convivial supper in the courtyard / where new residents met longtime neighbors / over shared dishes and live music.','convivial 修饰 supper；where 从句说明聚会中的社交情景。','共享食物音乐、邻里亲切交谈，符合宴聚友好氛围义。')],mistakes:[M('The convivial dinner was silent and hostile, and every guest was ordered to sit alone without speaking.','The austere dinner was silent and formal, and every guest was ordered to sit alone without speaking.','沉默、敌意且不许交谈的场合缺少 convivial 所含的友好欢聚氛围。','register')],quiz:[Q('convivial',1,1,'A convivial gathering is usually?',['friendly and lively','hostile and silent','strictly solitary'],'friendly and lively','Convivial describes warm social enjoyment.'),Q('convivial',2,1,'A convivial meal is most likely to include?',['good company and cheerful conversation','a ban on speaking and meeting','a laboratory experiment only'],'good company and cheerful conversation','The word often evokes pleasant eating and drinking together.'),Q('convivial',3,1,'Which evening sounds convivial?',['neighbors laughing over a shared supper','guests kept apart in a silent room','a power outage with no people present'],'neighbors laughing over a shared supper','The friendly social meal fits the adjective.'),Q('convivial',4,1,'Choose the closest meaning of convivial.',['sociable','convalescent','contradictory'],'sociable','A convivial atmosphere is sociable and enjoyable.') ]});
D('convoke',{etymology:E('convoke came from Latin convocare, con- “together” + vocare “call”; the formal verb means to summon people to an assembly.','convoke'),contexts:[C('convoke.s1','议会程序','The speaker will convoke the committee on Monday so its members can vote on the revised budget before the grant deadline.','议长将在周一召集委员会，以便成员能在拨款截止日期前表决修订预算。','The speaker will convoke the committee on Monday / so its members can vote / on the revised budget / before the grant deadline.','convoke 后接被召集的正式团体；so 引出召集目的。','正式召集委员会开会，符合词义。')],mistakes:[M('The chair convoked the committee by telling each member to stay home and never assemble.','The chair canceled the meeting and did not convoke the committee.','召集会议意味着要求成员到会；让他们不集会不是 convoke。')],quiz:[Q('convoke',1,1,'To convoke a council is to?',['call its members together for a meeting','dismiss every member permanently','publish the council’s minutes only'],'call its members together for a meeting','Convoke means to summon people to a formal assembly.'),Q('convoke',2,1,'Which sentence uses convoke naturally?',['The governor convoked the assembly for an emergency vote.','The governor convoked the rainfall into a cloud.','The assembly convoked itself by disappearing.'],'The governor convoked the assembly for an emergency vote.','A formal group is the object being summoned.'),Q('convoke',3,1,'A convoked panel must?',['assemble after being formally summoned','avoid meeting under all circumstances','repair the building’s roof'],'assemble after being formally summoned','The verb implies calling the panel to convene.'),Q('convoke',4,1,'The prefix con- in convoke contributes which idea?',['together','before','against'],'together','The Latin formation includes con- “together” plus vocare “call.”') ]});
D('cookery',{etymology:E('cookery is cook plus the activity or practice suffix -ery; cook is an old English word for a person who prepares food, borrowed from Latin coquus through Germanic forms.','cookery'),contexts:[C('cookery.s1','烹饪课程','The community center offers a cookery class on preserving seasonal vegetables, and participants leave with jars they prepared themselves.','社区中心开设季节蔬菜保存烹饪课，学员结束时会带走亲手制作的罐装蔬菜。','The community center offers a cookery class / on preserving seasonal vegetables / and participants leave / with jars they prepared themselves.','cookery class 指烹饪课程；on 后接课程主题。','课程教授食物制作与保存，属于烹饪活动/技艺。')],mistakes:[M('The cookery course taught students to repair car engines, replace brake pads, and test electrical wiring.','The mechanics course taught students to repair car engines, replace brake pads, and test electrical wiring.','修车与电气维修属于机械课程，不是 cookery（烹饪）。','word-choice')],quiz:[Q('cookery',1,1,'Cookery is the skill or activity of?',['preparing food','building a roof','writing a court judgment'],'preparing food','Cookery means cooking or the art of preparing food.'),Q('cookery',2,1,'A book on Italian cookery would most likely contain?',['recipes and food-preparation methods','instructions for operating a telescope','legal forms for transferring land'],'recipes and food-preparation methods','The subject is Italian cooking.'),Q('cookery',3,1,'Which course is a cookery course?',['learning to bake bread and prepare sauces','learning to solder circuit boards','learning to map the night sky'],'learning to bake bread and prepare sauces','Those activities involve preparing food.'),Q('cookery',4,1,'“Regional cookery” refers to?',['ways of cooking associated with a region','regional rules for voting','regional bus routes'],'ways of cooking associated with a region','Cookery can be modified by the cuisine’s region.') ]});
D('cookout',{etymology:E('cookout is an American English compound of cook and out, naming an informal meal prepared outdoors, commonly on a grill.','cookout'),contexts:[C('cookout.s1','家庭聚会','For the neighborhood cookout, Sam set up a charcoal grill in the garden and asked each family to bring a side dish to share.','为邻里露天烧烤聚会，萨姆在花园里架起炭火烤炉，并请每家带一道配菜分享。','For the neighborhood cookout / Sam set up a charcoal grill in the garden / and asked each family / to bring a side dish to share.','cookout 指在户外烹制并聚餐的活动；to bring 说明受邀者要做什么。','在花园架炉、邻里带菜共餐，符合露天烹食聚会义。')],mistakes:[M('The cookout was held in a sealed office kitchen with no outdoor cooking and no shared meal.','The indoor dinner was held in a sealed office kitchen with no outdoor cooking.','在室内且没有户外烹饪的聚会不能称为 cookout。','word-choice')],quiz:[Q('cookout',1,1,'At a cookout, food is typically?',['prepared and eaten outdoors','served only in a courtroom','kept uncooked in a freezer'],'prepared and eaten outdoors','A cookout is an informal outdoor meal, often grilled.'),Q('cookout',2,1,'Which plan describes a cookout?',['neighbors grill vegetables in a backyard and share dinner','students take a written exam in silence','workers inspect a factory conveyor'],'neighbors grill vegetables in a backyard and share dinner','Outdoor grilling and eating together fit the word.'),Q('cookout',3,1,'A family packs charcoal, burgers, and a picnic table for a?',['cookout','convalescence','conveyance'],'cookout','These items suggest outdoor cooking and a meal.'),Q('cookout',4,1,'The compound cookout most directly combines cooking with?',['being outside','a legal contract','a flower part'],'being outside','The out element signals an outdoor setting.') ]});
D('coolant',{etymology:E('coolant is formed from cool plus the substance suffix -ant, naming a fluid or material that carries heat away and keeps machinery cool.','coolant'),contexts:[C('coolant.s1','车辆保养','The mechanic checked the coolant level before a long drive and topped up the reservoir when it fell below the minimum mark.','长途驾驶前，技师检查了冷却液液位；发现低于最低刻度后便补满储液罐。','The mechanic checked the coolant level before a long drive / and topped up the reservoir / when it fell below the minimum mark.','coolant 是 level 的名词中心；when 从句说明何时补液。','储液罐中的液体帮助发动机散热，符合词义。')],mistakes:[M('The engine coolant was drained and replaced with dry sand, which circulated through the radiator to carry heat away.','The engine coolant was drained and replaced with fresh coolant, which circulated through the radiator to carry heat away.','干沙不能作为散热循环液；coolant 通常是流动的冷却介质。')],quiz:[Q('coolant',1,1,'Coolant in a car is used to?',['carry heat away from the engine','lubricate a printed page','increase the fuel tank’s size'],'carry heat away from the engine','Coolant helps regulate engine temperature.'),Q('coolant',2,1,'A mechanic checks the coolant reservoir because it contains?',['fluid used by the cooling system','spare tires','brake pads'],'fluid used by the cooling system','A reservoir stores the cooling fluid.'),Q('coolant',3,1,'Which substance is most likely coolant?',['a circulating liquid in a machine radiator','a solid note pinned to the dashboard','a belt carrying boxes in a warehouse'],'a circulating liquid in a machine radiator','Coolant carries heat through a cooling system.'),Q('coolant',4,1,'In coolant, the element cool points to its function of?',['reducing heat','creating a contract','growing a flower'],'reducing heat','The word names a heat-removing substance.') ]});
D('coop',{etymology:E('The enclosure noun coop is an old English word for a cage or pen; its deeper origin is uncertain. The verb arose from keeping something inside such an enclosure.','coop'),contexts:[C('coop.s2','动物福利','The rescue team refused to coop the injured owl in a narrow box for the night; they placed it in a roomy, ventilated enclosure instead.','救援队不肯把受伤的猫头鹰关进狭窄箱子过夜，而是把它安置在宽敞通风的围栏里。','The rescue team refused to coop the injured owl in a narrow box for the night / they placed it / in a roomy, ventilated enclosure instead.','coop 作及物动词，coop someone/something in/up 表示把其关在狭小空间。','把动物限制在狭小处所，体现动词义 s2。')],mistakes:[M('The keeper cooped the hens up by releasing them into a wide field where they could roam freely all day.','The keeper let the hens roam in a wide field rather than cooping them up in a small pen.','自由漫游与 cooped up 所表示的受限、被关起来相反。','confusable')],quiz:[Q('coop',1,1,'A chicken coop is?',['a small enclosure for chickens','a device that cools an engine','a musical instrument'],'a small enclosure for chickens','The noun names a cage or pen for poultry.'),Q('coop',2,2,'To coop a person up in a tiny room is to?',['confine the person there','invite the person to a feast','transfer the room’s ownership'],'confine the person there','The verb means to keep someone or an animal in a small space.'),Q('coop',3,1,'A farmer enters the coop to?',['tend the chickens in their enclosure','repair a steel converter','read a legal conveyance'],'tend the chickens in their enclosure','The noun refers to a poultry pen.'),Q('coop',4,2,'Which sentence uses coop as a verb?',['They cooped the hens up during the storm.','They painted the coop red.','They bought two new coops.'],'They cooped the hens up during the storm.','Cooped up is the verb phrase for confining the hens.') ]});
D('cooper',{etymology:E('Cooper, the craft noun, came through Middle English and Anglo-French forms from Latin cupa “cask or tub”; the verb developed from the craft of making or repairing casks.','cooper'),contexts:[C('cooper.s1','桶匠作坊','The cooper inspected each oak stave, fitted the curved pieces together, and tightened iron hoops around the barrel before it was filled with cider.','制桶匠检查每块橡木桶板，把弯曲木板拼合，再在装苹果酒前用铁箍箍紧木桶。','The cooper inspected each oak stave / fitted the curved pieces together / and tightened iron hoops around the barrel / before it was filled with cider.','cooper 是从事制桶手艺的人；三个并列过去式动词描述工序。','制作木桶并安装桶箍的人符合名词义 s1。')],mistakes:[M('The cooper repaired wooden casks for the brewery, but the report called her a cooper because she flew the aircraft.','The cooper repaired wooden casks for the brewery, while the aircraft’s second pilot was called a copilot.','木桶匠是 cooper；飞机副驾驶是 copilot，不能混淆。','confusable')],quiz:[Q('cooper',1,1,'A cooper traditionally makes or repairs?',['wooden barrels and casks','aircraft engines','flower petals'],'wooden barrels and casks','The craft noun means a maker or repairer of casks.'),Q('cooper',2,2,'If a cooper is hired to cooper a damaged barrel, the worker will?',['repair the barrel','fly the plane','prepare a legal deed'],'repair the barrel','The verb means to make or mend barrels.'),Q('cooper',3,1,'What tool would a cooper likely use?',['a hoop to bind barrel staves','a lens for measuring convexity','a microphone for a cookout'],'a hoop to bind barrel staves','Coopers assemble staves and secure them with hoops.'),Q('cooper',4,1,'Which job title matches a cooper?',['barrel maker','copilot','coppersmith'],'barrel maker','Coopers specialize in wooden barrels and casks.') ]});
D('cooperation',{etymology:E('Cooperation is co- “together” plus operation, from Latin cooperari “work together”; it names joint effort and, in context, willingness to comply.','cooperation'),contexts:[C('cooperation.s2','急救演练','The evacuation went smoothly because of the children’s cooperation: they followed the teacher’s directions, stayed with their group, and kept the exits clear.','疏散之所以顺利，得益于孩子们的配合：他们听从老师指示、留在小组中并保持出口畅通。','The evacuation went smoothly / because of the children’s cooperation / they followed the teacher’s directions / stayed with their group / and kept the exits clear.','cooperation 在此指配合指示；冒号列出配合的具体行为。','孩子按要求行动让演练顺利进行，对应配合义 s2。')],mistakes:[M('The crew’s cooperation prevented the rescue, because every member followed the safety instructions and helped one another.','The crew’s cooperation enabled the rescue, because every member followed the safety instructions and helped one another.','共同遵守指示并互相帮助促进而非阻止救援。')],quiz:[Q('cooperation',1,1,'Cooperation between two research teams means they?',['work together toward a shared aim','hide all results from one another','compete to prevent any progress'],'work together toward a shared aim','Cooperation is joint effort between people or groups.'),Q('cooperation',2,2,'A patient’s cooperation with a nurse may involve?',['following instructions during treatment','writing the nurse’s biography','refusing every request while claiming to comply'],'following instructions during treatment','Here cooperation means willingness to do what is asked.'),Q('cooperation',3,1,'Which action demonstrates cooperation?',['two departments share data to finish a project','one department destroys the other’s files','each group blocks the same emergency exit'],'two departments share data to finish a project','Sharing effort and information supports a common goal.'),Q('cooperation',4,2,'The rescue needed the crowd’s cooperation. The crowd should?',['follow directions and keep access clear','ignore marshals and block the route','vote on the spelling of rescue'],'follow directions and keep access clear','Compliance helps the rescue operation proceed.') ]});
D('cooperative',{etymology:E('Cooperative is formed from co- “together” and operate, from Latin cooperari “work together,” with -ive; as a noun it names a member-owned organization.','cooperative'),contexts:[C('cooperative.s2','农民合作社','The farmers formed a cooperative to buy seed in bulk, share cold-storage costs, and sell their produce through a shop owned by the members.','农民组建合作社以批量购买种子、分担冷藏成本，并通过成员共同拥有的商店销售农产品。','The farmers formed a cooperative / to buy seed in bulk / share cold-storage costs / and sell their produce / through a shop owned by the members.','cooperative 作可数名词，指成员共同拥有和经营的组织。','农民共同持有商店、分摊成本，符合合作社义 s2。')],mistakes:[M('The cooperative was owned and controlled by one outside landlord, while its supposed members had no say or share.','The company was owned and controlled by one outside landlord; it was not a member-owned cooperative.','成员所有、共同经营是合作社的关键特征；单一外部所有者不符。')],quiz:[Q('cooperative',1,2,'A housing cooperative is typically?',['owned or run by its members','a single person’s private hotel','a machine that carries packages'],'owned or run by its members','The noun means an organization owned and operated by members.'),Q('cooperative',2,1,'A cooperative child is described as?',['willing to work with others','unwilling to follow any shared plan','a legal transfer of property'],'willing to work with others','The adjective sense means working together willingly.'),Q('cooperative',3,2,'Members of a food cooperative generally?',['share ownership or control of the organization','rent each other’s names','serve as aircraft copilots'],'share ownership or control of the organization','The organization is member-owned and run.'),Q('cooperative',4,1,'Choose the ordinary adjective use.',['The witness was cooperative during the inquiry.','The witness was a cooperative during the inquiry.','The inquiry cooperative the witness.'],'The witness was cooperative during the inquiry.','The adjective describes willingness to assist.') ]});
D('coordination',{etymology:E('Coordination is coordinate plus -ion; coordinate comes from Latin coordinare, co- “together” + ordinare “arrange,” and refers to organizing parts or bodily movements.','coordination'),contexts:[C('coordination.s2','康复训练','After the stroke, the therapist used slow reaching exercises to improve Mei’s hand–eye coordination before she returned to cooking.','中风后，治疗师用缓慢的伸手练习改善梅的手眼协调能力，然后才让她重新做饭。','After the stroke / the therapist used slow reaching exercises / to improve Mei’s hand–eye coordination / before she returned to cooking.','coordination 修饰 hand–eye，指身体不同部位配合顺畅的能力。','手与眼配合动作的能力逐步恢复，符合身体协调义 s2。')],mistakes:[M('The dancer’s coordination was excellent, although she could not make her arms and legs move together or keep her balance.','The dancer’s coordination was poor, since she could not make her arms and legs move together or keep her balance.','动作不能配合且失去平衡表现协调能力差，而非 excellent。')],quiz:[Q('coordination',1,2,'Good hand–eye coordination helps someone?',['guide the hands accurately using visual information','transfer a house title','heat a room by air circulation'],'guide the hands accurately using visual information','The bodily sense concerns smooth combined movement.'),Q('coordination',2,1,'Coordination among rescue teams means?',['organizing their actions so they fit together','giving every team an unrelated deadline','asking teams never to communicate'],'organizing their actions so they fit together','The organizational sense is arranging parts to work together.'),Q('coordination',3,2,'Which exercise tests coordination?',['catching a ball while tracking its movement','memorizing a single name','measuring the temperature of coolant'],'catching a ball while tracking its movement','The task requires eyes and hands to work together.'),Q('coordination',4,1,'A coordinator improves project coordination by?',['aligning schedules and responsibilities','assigning all tasks twice with no plan','stopping every team from sharing updates'],'aligning schedules and responsibilities','Coordination organizes parts into a coherent whole.') ]});
D('coordinator',{etymology:E('Coordinator is coordinate plus agent suffix -or; coordinate comes from Latin coordinare, “arrange together,” and the noun usually names a person who organizes a project.','coordinator'),contexts:[C('coordinator.s1','志愿服务','The volunteer coordinator assigned each team a route, checked that radios were charged, and arranged a backup driver for the supply van.','志愿者协调员为每支队伍分配路线、确认对讲机已充电，并为补给车安排了备用司机。','The volunteer coordinator assigned each team a route / checked that radios were charged / and arranged a backup driver / for the supply van.','coordinator 是执行统筹工作的人员；三个并列动词说明职责。','分配路线、检查设备、安排司机体现组织项目的工作。')],mistakes:[M('The coordinator organized every team’s schedule, but the event notes called the person a coordinator because they had no organizing duties.','The coordinator organized every team’s schedule, which is exactly the kind of work the role involves.','负责协调组织的人正是 coordinator；否认其承担组织职责与语境冲突。')],quiz:[Q('coordinator',1,1,'A project coordinator most likely?',['organizes tasks, people, or schedules','writes the project’s final poem only','converts iron into steel'],'organizes tasks, people, or schedules','A coordinator arranges parts of a project so they work together.'),Q('coordinator',2,2,'The coordinator of a relief drive arranged?',['volunteers, deliveries, and timing','the petals of a flower','a patient’s convalescence'],'volunteers, deliveries, and timing','These tasks require project organization.'),Q('coordinator',3,1,'Which person is a coordinator?',['the staff member aligning several teams’ schedules','a passerby with no role in the event','a machine belt moving cartons'],'the staff member aligning several teams’ schedules','Aligning teams is coordination work.'),Q('coordinator',4,1,'In its rarer sense, a coordinator can be?',['a thing of the same rank or order as another','a person who never compares anything','a medical cooling fluid'],'a thing of the same rank or order as another','The less common noun sense means a coordinate or corresponding thing.') ]});
D('copilot',{etymology:E('Copilot combines co- “jointly” and pilot; co- is from Latin com-, “with.” It names the second pilot who shares flying duties with the pilot in command.','copilot'),contexts:[C('copilot.s1','航空运行','The copilot read the approach checklist aloud while the captain monitored the instruments and confirmed the runway assignment with air traffic control.','副驾驶大声核对进近清单，同时机长监控仪表，并与空管确认跑道安排。','The copilot read the approach checklist aloud / while the captain monitored the instruments / and confirmed the runway assignment / with air traffic control.','copilot 是与机长共同驾驶的飞行员；while 表示两位机组人员同时履职。','副驾驶负责核对飞行清单并分担驾驶任务。')],mistakes:[M('The copilot shared the flight deck duties with the captain, but the flight log said a copilot is a passenger with no flying role.','The copilot shared the flight deck duties with the captain, unlike a passenger with no flying role.','副驾驶是共同承担驾驶职责的飞行员，并非普通乘客。')],quiz:[Q('copilot',1,1,'A copilot works alongside?',['the pilot in command','a ship’s cooper','a newspaper contributor'],'the pilot in command','A copilot shares flying duties with the main pilot.'),Q('copilot',2,1,'During a flight, the copilot may?',['read checklists and monitor instruments','write a land conveyance','make a steel cornet'],'read checklists and monitor instruments','These are typical shared cockpit responsibilities.'),Q('copilot',3,1,'Which person is the copilot?',['the second pilot assisting with the flight','a passenger seated by the window','the person who owns the airport'],'the second pilot assisting with the flight','The term names a pilot who shares duties.'),Q('copilot',4,1,'The prefix co- in copilot indicates?',['working jointly','opposition','a flower crown'],'working jointly','Co- means together or jointly.') ]});
D('copious',{etymology:E('Copious came through French from Latin copiosus “abundant,” from copia “plenty”; it describes a large quantity or, of writing, extensive detail.','copious'),contexts:[C('copious.s2','田野笔记','The botanist kept copious notes on each plot, recording soil moisture, shade, flowering dates, and the insects seen during every visit.','植物学家对每块样地都做了详尽笔记，记录土壤湿度、遮阴、开花日期以及每次到访时见到的昆虫。','The botanist kept copious notes on each plot / recording soil moisture, shade, flowering dates / and the insects seen during every visit.','copious 修饰 notes，表示信息丰富、记录详尽；recording 列出细节。','多项观察数据和重复记录体现详尽义 s2。')],mistakes:[M('The report contained copious detail: it consisted of one empty page with no measurements or observations.','The report contained little detail: it consisted of one empty page with no measurements or observations.','空白页没有大量细节，与 copious detail 相反。')],quiz:[Q('copious',1,1,'Copious rainfall means?',['a large amount of rain','a few isolated drops only','rain that never reaches the ground'],'a large amount of rain','Copious means existing or produced in large quantities.'),Q('copious',2,2,'Copious notes are notes that are?',['abundant and detailed','missing nearly all information','limited to one unlabelled word'],'abundant and detailed','For information, copious can mean extensive or full of detail.'),Q('copious',3,1,'Which phrase uses copious naturally?',['copious evidence supporting the conclusion','copious one drop in an empty jar','copious silence with no sound recorded'],'copious evidence supporting the conclusion','Copious evidence means a large body of supporting material.'),Q('copious',4,1,'A writer who provides copious examples provides?',['many examples','exactly one example','no examples at all'],'many examples','The adjective signals a plentiful number.') ]});
D('coppersmith',{etymology:E('Coppersmith is a transparent compound of copper, the metal, and smith, a craft worker who shapes or works metal.','coppersmith'),contexts:[C('coppersmith.s1','金属工艺','The coppersmith hammered a sheet into a shallow serving bowl, then soldered a handle onto its rim and polished the surface.','铜匠把铜片锤打成浅口餐碗，再将把手焊在碗沿上并打磨表面。','The coppersmith hammered a sheet into a shallow serving bowl / then soldered a handle onto its rim / and polished the surface.','coppersmith 是从事铜器制作的工匠；并列动词描述加工步骤。','锤打铜片并焊接把手，符合铜匠工艺。')],mistakes:[M('The coppersmith shaped the copper bowl from aluminum and never worked with copper at any stage.','The metalsmith shaped the bowl from aluminum; a coppersmith works with copper.','只加工铝而未接触铜，称为铝匠/金属匠，不是 coppersmith。','word-choice')],quiz:[Q('coppersmith',1,1,'A coppersmith works mainly with?',['copper','oak barrel staves','aircraft flight plans'],'copper','The compound names a smith specializing in copper.'),Q('coppersmith',2,1,'Which task suits a coppersmith?',['hammering a copper sheet into a vessel','editing a magazine article','measuring a flower corolla'],'hammering a copper sheet into a vessel','Shaping copper objects is the craft.'),Q('coppersmith',3,1,'The second part, smith, refers to?',['a person who works metal','a type of bird','a legal transfer'],'a person who works metal','A smith is a metalworker or craft worker.'),Q('coppersmith',4,1,'A copper roof repaired by a coppersmith is made of?',['copper sheets','steel flower petals','wooden barrels'],'copper sheets','Copper is the metal that gives the craft its name.') ]});
D('cordwainer',{etymology:E('Cordwainer came through Middle English from Anglo-French cordewaner, a maker of fine leather shoes; the name is traditionally linked to Cordoba leather, though the deeper naming history is not entirely certain.','cordwainer'),contexts:[C('cordwainer.s1','传统制鞋','The cordwainer cut supple leather for a custom pair of boots, stitched each upper by hand, and fitted the soles before the customer tried them on.','皮鞋匠为一双定制靴裁剪柔韧皮革，手工缝合鞋面，并在顾客试穿前装上鞋底。','The cordwainer cut supple leather for a custom pair of boots / stitched each upper by hand / and fitted the soles / before the customer tried them on.','cordwainer 是制鞋手艺人；并列过去式动词呈现制鞋步骤。','用皮革制作定制鞋靴，符合历史职业义。')],mistakes:[M('The cordwainer repaired a customer’s leather shoes, but the museum label defined a cordwainer as a person who makes wooden barrels.','The cordwainer repaired a customer’s leather shoes; a cooper is a person who makes wooden barrels.','制鞋匠 cordwainer 与制桶工 cooper 是不同手艺职业。','confusable')],quiz:[Q('cordwainer',1,1,'A cordwainer is traditionally a maker of?',['leather shoes','wooden barrels','brass wind instruments'],'leather shoes','The historical craft noun means a shoemaker, especially of fine leather shoes.'),Q('cordwainer',2,1,'What material would a cordwainer handle?',['leather for shoe uppers','molten iron for steel','coriander seeds for spice'],'leather for shoe uppers','Leather is used to make the shoes in this craft.'),Q('cordwainer',3,1,'Which modern occupation is closest to a cordwainer?',['custom shoemaker','airline copilot','plant taxonomist'],'custom shoemaker','Cordwainer is an old name for a shoemaker.'),Q('cordwainer',4,1,'The word cordwainer refers to someone who?',['makes shoes','keeps a poultry coop','calls a council to meet'],'makes shoes','The defining work is shoe-making.') ]});
D('coriander',{etymology:E('Coriander came through Latin coriandrum from Greek koriannon; English uses the name for the herb and its aromatic seeds.','coriander'),contexts:[C('coriander.s1','菜谱配料','The cook added chopped coriander leaves at the end of the curry, then toasted the seeds separately to release their warmer, citrus-like aroma.','厨师在咖喱快做好时加入切碎的香菜叶，又把种子单独烘烤以释放更温暖、带柑橘气息的香味。','The cook added chopped coriander leaves at the end of the curry / then toasted the seeds separately / to release their warmer, citrus-like aroma.','coriander 可指叶或种子；leaves 和 seeds 在这里具体区分植物的两种调味部分。','新鲜叶与芳香种子均作调味料，符合词条义。')],mistakes:[M('The recipe calls for coriander leaves, so the cook substitutes an unrelated metal washer to provide the same herbal flavor.','The recipe calls for coriander leaves, so the cook uses the herb’s fresh leaves for the herbal flavor.','金属垫圈不是香草，不可能替代 coriander 提供香味。','word-choice')],quiz:[Q('coriander',1,1,'Coriander is commonly used to flavor?',['food','a legal contract','a steel furnace'],'food','Coriander leaves and seeds are culinary herbs and spices.'),Q('coriander',2,1,'Which parts of coriander may be used in cooking?',['fresh leaves and dried seeds','only its metal roots','its bird feathers'],'fresh leaves and dried seeds','Both the leaves and seeds are used as flavorings.'),Q('coriander',3,1,'Toasting coriander seeds is done to?',['release their aroma','make them into flower petals','turn them into coolant'],'release their aroma','Heating spices can bring out their flavor and scent.'),Q('coriander',4,1,'A cook garnishes soup with chopped coriander. The garnish is?',['an herb','a shoemaker’s tool','a type of legal deed'],'an herb','Coriander is a plant used to flavor food.') ]});
D('cormorant',{etymology:E('Cormorant came into English through French cormoran; older forms are associated with the “sea raven” expression, though the exact development is uncertain. The bird name is the ordinary use.','cormorant'),contexts:[C('cormorant.s1','海鸟观察','A cormorant dived beneath the harbor surface, pursued a small fish, and returned to a piling with its wings spread to dry.','一只鸬鹚潜入港湾水下追逐小鱼，随后回到系船桩上张开翅膀晾干。','A cormorant dived beneath the harbor surface / pursued a small fish / and returned to a piling / with its wings spread to dry.','cormorant 作鸟名；with its wings spread 补充鸟停栖时的姿态。','潜水捕鱼的深色水鸟，符合 s1。')],mistakes:[M('The cormorant caught fish by swimming under water, but the field guide identified it as a small tree frog.','The cormorant caught fish by swimming under water, and the field guide identified it as a diving water bird.','会潜水捕鱼的鸬鹚是水鸟，不是树蛙。','confusable')],quiz:[Q('cormorant',1,1,'A cormorant is a bird known for?',['diving to catch fish','building steel barrels','pollinating only desert cactus'],'diving to catch fish','Cormorants are large water birds that dive for fish.'),Q('cormorant',2,2,'Calling a miser a cormorant uses which sense?',['an informal comparison to extreme greed','the literal name of a sea bird','a term for a brass instrument'],'an informal comparison to extreme greed','The word can figuratively describe someone extremely greedy.'),Q('cormorant',3,1,'Where is a literal cormorant most at home?',['along a coast or lake','inside a dry courtroom','in a flower’s corolla'],'along a coast or lake','It is a water bird that hunts fish.'),Q('cormorant',4,1,'A bird spreading its wings after diving is likely?',['a cormorant','a cordwainer','a conveyor'],'a cormorant','Cormorants often hold their wings out to dry after diving.') ]});
D('cornet',{etymology:E('Cornet came from French cornet, literally “little horn,” a diminutive of corne “horn”; the instrument is horn-like, while a paper cone or wafer is another sense.','cornet'),contexts:[C('cornet.s2','冰淇淋摊','The vendor filled a crisp cornet with two scoops of ice cream and handed it to the child before the chocolate began to melt.','摊主把两球冰淇淋装进酥脆的蛋筒，在巧克力开始融化前递给孩子。','The vendor filled a crisp cornet with two scoops of ice cream / and handed it to the child / before the chocolate began to melt.','cornet 在此是锥形薄脆筒；fill A with B 表示把冰淇淋装入蛋筒。','可食用的锥形威化筒，符合 s2。')],mistakes:[M('The ice-cream seller placed two scoops in a cornet, a flat metal plate with no sides or point.','The ice-cream seller placed two scoops in a cornet, a crisp cone-shaped wafer.','蛋筒应是锥形容器，不是无侧无尖的平盘。')],quiz:[Q('cornet',1,2,'An ice-cream cornet is?',['a cone-shaped wafer','a bird that dives for fish','a metal barrel'],'a cone-shaped wafer','This sense is a crisp cone or paper cone.'),Q('cornet',2,1,'A musician playing a cornet uses?',['a compact brass instrument','a flower’s outer leaves','a computer converter'],'a compact brass instrument','The instrument is a brass wind instrument similar to a trumpet.'),Q('cornet',3,1,'Which item can hold an ice-cream scoop?',['a cornet','a cormorant','a coolant'],'a cornet','The cone-shaped wafer is designed to hold ice cream.'),Q('cornet',4,1,'The name cornet is historically related to the idea of a?',['small horn','crown of petals','legal agreement'],'small horn','The French source literally meant “little horn.”') ]});
D('corolla',{etymology:E('Corolla is a Latin loan meaning “little crown,” the diminutive of corona; in botany it names all the petals of a flower considered together.','corolla'),contexts:[C('corolla.s1','植物形态','The botanist described the flower’s corolla as pale violet, with five fused petals surrounding the narrow throat of the bloom.','植物学家把花冠描述为浅紫色，由五片合生花瓣围绕花朵狭窄的喉部。','The botanist described the flower’s corolla as pale violet / with five fused petals / surrounding the narrow throat of the bloom.','corolla 指花瓣整体组成的花冠；with 短语补充花冠结构。','五片合生花瓣作为一组构成花冠。')],mistakes:[M('The corolla consists of the roots beneath the soil, while the flower’s petals are a completely separate structure.','The corolla consists of the flower’s petals considered together, while the roots lie beneath the soil.','corolla 是花瓣整体，不是地下根系。','confusable')],quiz:[Q('corolla',1,1,'In botany, the corolla is?',['the petals of a flower taken together','the underground root system','a bird’s beak'],'the petals of a flower taken together','Corolla names the flower’s collective petals.'),Q('corolla',2,1,'A botanist counting the corolla is examining?',['the flower’s petal ring','the stem’s bark only','a solar eclipse'],'the flower’s petal ring','The corolla is the often colorful inner ring of petals.'),Q('corolla',3,1,'Which part is not the corolla?',['the roots under the soil','the joined flower petals','the petals around the bloom'],'the roots under the soil','Roots are not petals and do not form the corolla.'),Q('corolla',4,1,'The Latin source of corolla means?',['little crown','little bird','great agreement'],'little crown','Corolla is the diminutive of Latin corona, “crown.”') ]});
D('corollary',{etymology:E('Corollary came through French from medieval Latin corollarium, originally an extra or reward, from Latin corolla “small garland”; English developed the sense of a result or proposition that follows.','corollary'),contexts:[C('corollary.s2','几何证明','The theorem establishes that the two angles are equal; as a corollary, the triangle is isosceles because equal angles face equal sides.','定理证明两个角相等；由此可推论该三角形为等腰三角形，因为等角所对的边相等。','The theorem establishes that the two angles are equal / as a corollary / the triangle is isosceles / because equal angles face equal sides.','as a corollary 引入由已证明结果直接推出的命题；because 说明依据。','三角形等腰性质直接由已证角相等推出，对应推论义 s2。')],mistakes:[M('The corollary was unrelated to the theorem and contradicted its conclusion, so it followed directly from the proof.','The corollary followed directly from the theorem’s conclusion and did not contradict it.','与定理无关且相矛盾的命题不能说是其直接推论。','meaning')],quiz:[Q('corollary',1,2,'A corollary in a proof is a statement that?',['follows directly from a result already established','introduces an unrelated new problem','contradicts every earlier result'],'follows directly from a result already established','A corollary is a proposition that follows from an established one.'),Q('corollary',2,1,'A natural corollary of a long drought may be?',['water restrictions','a guaranteed increase in rainfall','a change in the alphabet'],'water restrictions','Restrictions can result from a drought.'),Q('corollary',3,1,'Which sentence uses corollary correctly?',['A corollary of the ruling was that the fee had to be refunded.','The corollary contradicted the ruling and had no connection to it.','She corollary the letter yesterday.'],'A corollary of the ruling was that the fee had to be refunded.','The refund requirement follows as a result of the ruling.'),Q('corollary',4,1,'A corollary to the theorem is best described as?',['a consequence or direct inference','a totally unrelated rumor','the theorem’s spelling'],'a consequence or direct inference','The noun means a natural result or proposition that follows.') ]});
D('corona',{etymology:E('Corona came from Latin corona “crown or wreath”; English uses it for the sun’s faint outer atmosphere and for crown-shaped structures.','corona'),contexts:[C('corona.s1','天文观测','During the total eclipse, observers saw the sun’s corona as a pale halo around the dark disk, a feature normally hidden by the bright photosphere.','日全食期间，观测者看到太阳日冕如苍白光环环绕暗色圆盘；平时这一结构被明亮的光球遮住。','During the total eclipse / observers saw the sun’s corona as a pale halo / around the dark disk / a feature normally hidden by the bright photosphere.','corona’s 所有格表明日冕属于太阳；as 引出看到的形态。','日食时可见的太阳外层光环是日冕义 s1。')],mistakes:[M('The sun’s corona is the innermost bright layer visible at every moment, never observed around the eclipsed disk.','The sun’s corona is its faint outer atmosphere, especially visible around the eclipsed disk during totality.','日冕是外层大气，日全食时因光球遮挡消失而更易观察。')],quiz:[Q('corona',1,1,'During a total solar eclipse, the corona appears?',['as a faint halo around the sun','as a layer deep beneath Earth’s oceans','as a flower’s root'],'as a faint halo around the sun','The solar corona is the sun’s faint outer atmosphere.'),Q('corona',2,2,'A plant’s corona may be?',['a crown-shaped part','a bird that dives for fish','a steelmaking furnace'],'a crown-shaped part','Corona can name a crown-like structure on a body or plant.'),Q('corona',3,1,'Which instrument is designed to study the solar corona?',['a solar telescope','a barrel hoop','a cookery knife'],'a solar telescope','Astronomers use specialized instruments to observe the sun’s outer atmosphere.'),Q('corona',4,1,'The Latin word corona meant?',['crown or wreath','river current','a person who writes a biography'],'crown or wreath','The Latin source provides the crown-shaped naming idea.') ]});
D('coronavirus',{etymology:E('Coronavirus combines corona, Latin for “crown,” and virus; the name refers to crown-like surface projections seen on the virus particles.','coronavirus'),contexts:[C('coronavirus.s1','病毒学实验室','Researchers compared the surface proteins of a coronavirus with those of related viruses to identify which structures allowed it to enter airway cells.','研究人员将一种冠状病毒的表面蛋白与相关病毒的蛋白比较，以辨认哪些结构能使其进入呼吸道细胞。','Researchers compared the surface proteins of a coronavirus / with those of related viruses / to identify which structures / allowed it to enter airway cells.','a coronavirus 指冠状病毒科的一种病毒；to identify 表示比较目的。','表面蛋白及感染细胞的机制符合病毒义。')],mistakes:[M('The report identifies coronavirus as the name of one bacterial species, not a group of RNA viruses.','The report identifies coronavirus as a family of RNA viruses, not a bacterial species.','冠状病毒是病毒而非细菌；该词还指一个病毒科而非单一细菌。','confusable')],quiz:[Q('coronavirus',1,1,'Coronavirus names?',['a family of RNA viruses','a group of copperworking tools','a flowering plant’s petals'],'a family of RNA viruses','Coronaviruses are RNA viruses, some of which infect humans.'),Q('coronavirus',2,1,'The “corona” part of the name refers to?',['crown-like projections on the virus surface','a crown worn by a patient','the virus’s ability to form flowers'],'crown-like projections on the virus surface','The visible surface proteins suggest a crown-like outline.'),Q('coronavirus',3,1,'A coronavirus can cause illness in?',['humans and other animals','only metal objects','only plants with corollas'],'humans and other animals','Some members of the family infect humans and cause respiratory illness.'),Q('coronavirus',4,1,'Which statement is accurate?',['COVID-19 is caused by a coronavirus, but coronavirus names a broader family.','Coronavirus is a synonym for every bacterium.','Every coronavirus causes exactly the same disease.'],'COVID-19 is caused by a coronavirus, but coronavirus names a broader family.','The word usually denotes the virus family; one member caused COVID-19.') ]});
D('corporate',{etymology:E('Corporate came from Latin corporatus, “formed into a body,” from corpus “body”; English uses it for companies and for groups treated as legal persons.','corporate'),contexts:[C('corporate.s2','公司注册','The board approved a corporate resolution authorizing the nonprofit to sign the lease, because the organization acts as one legal body distinct from its members.','董事会通过了一项法人决议，授权非营利组织签署租约，因为该组织作为独立于成员的一个法律实体行事。','The board approved a corporate resolution / authorizing the nonprofit to sign the lease / because the organization acts as one legal body / distinct from its members.','corporate 修饰 resolution；because 从句解释组织作为法人团体的性质。','组织以独立法律实体身份承担义务，符合法人/社团义 s2。')],mistakes:[M('The corporate entity has no separate legal existence and every member is personally identical to the organization under the law.','The corporate entity has a legal identity distinct from its individual members.','公司/法人团体在法律上作为一个整体，不等同于每一名成员个人。','meaning')],quiz:[Q('corporate',1,2,'A corporate body is?',['a group treated as one legal entity','a single employee’s lunch box','a flower’s petal ring'],'a group treated as one legal entity','The legal sense treats the organization as a body.'),Q('corporate',2,1,'Corporate policy concerns?',['rules set by or for a company','the study of the sun’s corona','the care of a convalescent'],'rules set by or for a company','The common adjective sense relates to a company or business.'),Q('corporate',3,1,'A corporate decision is made by?',['a company or its authorized governing body','a cormorant in a harbor','a conveyor belt'],'a company or its authorized governing body','Corporate describes a company’s action or policy.'),Q('corporate',4,2,'Which is a corporate entity?',['a legally recognized organization','an individual flower petal','a single informal dinner'],'a legally recognized organization','A corporation or similar body exists as a legal group.') ]});
D('corporeal',{etymology:E('Corporeal came through French from Latin corporeus, from corpus “body”; the adjective refers to the physical body or material existence.','corporeal'),contexts:[C('corporeal.s1','哲学讨论','The philosopher distinguished corporeal objects, which occupy space and can be touched, from abstract ideas such as justice and number.','哲学家将占据空间、可以触摸的有形物体与正义、数字等抽象观念区分开来。','The philosopher distinguished corporeal objects / which occupy space and can be touched / from abstract ideas / such as justice and number.','corporeal 修饰 objects；which 引导定语从句说明有形物的特点。','占据空间并可触摸，符合肉体/物质存在义。')],mistakes:[M('A corporeal object is entirely abstract, has no physical form, and cannot occupy space.','An incorporeal object is abstract and has no physical form; a corporeal object is physical.','无形抽象的性质与 corporeal（有形、物质的）相反。','confusable')],quiz:[Q('corporeal',1,1,'A corporeal thing is?',['physical or material','a legal letter exchange','a mathematical inference'],'physical or material','Corporeal relates to the body or material existence.'),Q('corporeal',2,1,'Which example is corporeal?',['a stone that can be held','the idea of fairness by itself','a theorem with no physical copy'],'a stone that can be held','The stone has physical substance and can be touched.'),Q('corporeal',3,1,'A corporeal body differs from a spirit in being?',['material and physical','a type of flower','a formal meeting'],'material and physical','The adjective contrasts physical matter with spirit or abstraction.'),Q('corporeal',4,1,'Choose the correct contrast.',['corporeal: bodily; incorporeal: without physical form','corporeal: a crown; incorporeal: a bird','both mean easy to transport'],'corporeal: bodily; incorporeal: without physical form','The prefix in- reverses the physical sense.') ]});
D('corpulent',{etymology:E('Corpulent came from Latin corpulentus “stout,” from corpus “body”; it is a formal adjective for a very large or heavy build.','corpulent'),contexts:[C('corpulent.s2','历史肖像','The memoir described the corpulent mayor as broad and heavyset, but focused on his speeches and political choices rather than treating his body as a joke.','回忆录把市长描写为身材宽大、体格肥硕，但着重讲他的演说和政治选择，并未拿他的身体开玩笑。','The memoir described the corpulent mayor as broad and heavyset / but focused on his speeches and political choices / rather than treating his body as a joke.','corpulent 是较正式的体格描写词；rather than 对比叙述的关注点。','broad and heavyset 直接体现大而壮的体格义 s2。')],mistakes:[M('The corpulent portrait showed an extremely thin figure with no bulk or heaviness at all.','The slender portrait showed an extremely thin figure with no bulk or heaviness at all.','corpulent 表示体格肥大/壮实，不表示极瘦；这里 slender 才符合描述。','confusable')],quiz:[Q('corpulent',1,1,'A corpulent person is described as?',['large and heavy in build','exceptionally thin','a professional correspondent'],'large and heavy in build','Corpulent is a formal word for a fat or heavily built body.'),Q('corpulent',2,2,'Which description fits the less common build sense?',['broad and solidly built','tiny and weightless','a set of written letters'],'broad and solidly built','The word can describe a large, heavy build.'),Q('corpulent',3,1,'Which is closest in meaning to corpulent?',['stout','skeletal','conversant'],'stout','Stout is a near synonym for a heavy build.'),Q('corpulent',4,1,'A corpulent statue would have?',['a bulky body shape','no physical form whatsoever','only a narrow flat outline'],'a bulky body shape','The adjective concerns bodily size and build.') ]});
D('corpus',{etymology:E('Corpus is a direct Latin loan meaning “body.” English uses it for a structured body of texts and for the main or complete body of writings.','corpus'),contexts:[C('corpus.s1','语言学研究','The linguist built a corpus of recorded interviews, tagged each speaker’s turns, and searched the collection for regional forms of the past tense.','语言学家建立了一个录音访谈语料库，为每位说话人的话轮标注标签，并检索其中的过去时地域变体。','The linguist built a corpus of recorded interviews / tagged each speaker’s turns / and searched the collection / for regional forms of the past tense.','a corpus of + 文本/口语材料表示可供研究的大型语料集合。','标注、检索访谈中的语言模式，符合语料库义 s1。')],mistakes:[M('The linguist called a corpus a random pile of unrecorded opinions that could not be searched or studied.','The linguist called a corpus an organized collection of texts or speech assembled for study.','语料库是供研究的文本/口语材料集合，不是无法检索的随机意见。')],quiz:[Q('corpus',1,1,'A linguistic corpus is?',['a collection of texts or speech used for study','a single unrecorded conversation','a bird enclosure'],'a collection of texts or speech used for study','A corpus is a large body of language data.'),Q('corpus',2,2,'A corpus of an author’s works means?',['the collected body of the author’s writings','only the author’s final sentence','a legal transfer of the author’s house'],'the collected body of the author’s writings','Corpus can mean a complete collection of writings.'),Q('corpus',3,1,'Researchers search a corpus to?',['find patterns in language data','raise the temperature of coolant','shape copper by hammering'],'find patterns in language data','The collection supports systematic language study.'),Q('corpus',4,1,'Which material could form a corpus?',['thousands of tagged news articles','one blank card','a metal converter with no text'],'thousands of tagged news articles','A large collection of text is suitable corpus data.') ]});
D('corral',{etymology:E('Corral came from Spanish corral “pen or enclosure,” of uncertain deeper origin; English uses it as a noun for a livestock enclosure and as a verb for gathering animals into one.','corral'),contexts:[C('corral.s2','牧场管理','Two ranch hands corralled the escaped calves before dark, guiding them through a narrow gate into the fenced pasture beside the barn.','两名牧场工人在天黑前把逃跑的小牛赶进围栏，引导它们穿过窄门进入谷仓旁的圈养牧场。','Two ranch hands corralled the escaped calves before dark / guiding them through a narrow gate / into the fenced pasture / beside the barn.','corral 作及物动词，表示把动物赶拢并限制在圈栏内。','牧场工人把牛群赶入围栏，符合动词义 s2。')],mistakes:[M('The ranch hands corralled the cattle by opening every gate and letting the animals scatter across the open plain.','The ranch hands released the cattle by opening every gate and letting the animals scatter across the open plain.','放散牛群与 corral（聚拢赶入围栏）含义相反。','confusable')],quiz:[Q('corral',1,2,'To corral cattle is to?',['gather them into an enclosure','release them to scatter widely','weigh each animal separately'],'gather them into an enclosure','The verb means to gather or drive animals into a confined space.'),Q('corral',2,1,'A corral on a ranch is?',['a fenced pen for livestock','a flower’s petal ring','a formal legal letter'],'a fenced pen for livestock','The noun names an enclosure made with posts or rails.'),Q('corral',3,2,'A team corralled the escaped horses. What happened?',['they drove the horses together into a confined area','they turned the horses into birds','they let the horses roam farther away'],'they drove the horses together into a confined area','The verb captures gathering and confining.'),Q('corral',4,1,'Which sentence uses corral as a noun?',['The sheep rested in the corral.','The riders corral the sheep.','The sheep corralled quickly.'],'The sheep rested in the corral.','Here corral names the livestock enclosure.') ]});
D('correlated',{etymology:E('Correlated is the past participle of correlate, formed from co- “together” and relate; it describes things that show a statistical or regular connection.','correlated'),contexts:[C('correlated.s1','数据分析','Across the study sites, evening temperature was correlated with insect activity, but the researchers tested other factors before claiming that warmth caused the increase.','在各研究地点，傍晚气温与昆虫活动呈相关关系；不过研究人员在声称升温导致活动增加前，先检验了其他因素。','Across the study sites / evening temperature was correlated with insect activity / but the researchers tested other factors / before claiming that warmth caused the increase.','be correlated with 表示两变量存在统计联系；but 引出相关不等于因果的谨慎说明。','数据表明两项变化关联，并未直接断言单一因果。')],mistakes:[M('The variables were correlated, so the study proved beyond doubt that changing one variable caused the other to change.','The variables were correlated, but that association alone did not prove that one caused the other.','相关性本身不能证明因果关系。','usage')],quiz:[Q('correlated',1,1,'Two variables are correlated when they?',['show a regular or statistical relationship','are proven to have a direct causal link in every case','have exactly the same name'],'show a regular or statistical relationship','Correlation describes an association and does not by itself prove cause.'),Q('correlated',2,1,'Sales rose when temperatures rose. The two measures were?',['correlated','contrite','corporeal'],'correlated','They changed together, indicating an association.'),Q('correlated',3,1,'What cannot be concluded from correlation alone?',['that one variable definitely caused the other','that the variables changed together','that the association merits study'],'that one variable definitely caused the other','Correlation by itself does not establish causation.'),Q('correlated',4,1,'Choose the standard construction.',['The survey result was correlated with age.','The survey result was correlated from age.','The survey result correlated of age.'],'The survey result was correlated with age.','The usual pattern is be correlated with something.') ]});
D('correlation',{etymology:E('Correlation is correlate plus -ion; correlate combines co- “together” with relate and names a statistical or regular connection between changing things.','correlation'),contexts:[C('correlation.s1','医学统计','The study found a correlation between sleep duration and reaction time, yet its observational design could not establish that one directly caused the other.','研究发现睡眠时长与反应时间之间存在相关关系，但其观察性设计不能证明一者直接导致另一者。','The study found a correlation between sleep duration and reaction time / yet its observational design / could not establish / that one directly caused the other.','a correlation between A and B 表示两者相关；yet 限定因果推断。','两变量呈统计联系而因果未定，符合 s1。')],mistakes:[M('A correlation between ice-cream sales and swimming accidents proves that buying ice cream directly causes accidents.','A correlation between ice-cream sales and swimming accidents may reflect warmer weather affecting both; it does not alone prove causation.','相关关系可能由共同因素造成，不能直接当作因果证明。','usage')],quiz:[Q('correlation',1,1,'A correlation between A and B means?',['they tend to vary in a related way','A must always cause B','they are the same object'],'they tend to vary in a related way','Correlation is a relationship in which values tend to change together.'),Q('correlation',2,2,'A positive correlation may show that?',['two measures rise together','every low value in one forces a high value in the other','the measures have no recorded connection'],'two measures rise together','Positive association means larger values tend to accompany larger values.'),Q('correlation',3,1,'Which phrase uses correlation correctly?',['a correlation between rainfall and river level','a correlation of the letter to its envelope','a correlation that proves causation automatically'],'a correlation between rainfall and river level','Between is standard for naming the two related measures.'),Q('correlation',4,1,'The presence of correlation by itself does not establish?',['causation','an association','a pattern in the data'],'causation','A relationship can exist without one variable causing the other.') ]});
D('correspondence',{etymology:E('Correspondence came through French correspondre from medieval Latin correspondere, co- “together” + respondere “answer”; it developed senses of exchanged letters and agreement.','correspondence'),contexts:[C('correspondence.s2','档案核验','The dates in the shipping log showed a close correspondence with the harbor records, allowing the archivist to match each delivery to a vessel.','航运日志中的日期与港口记录高度吻合，使档案员能够把每次交付对应到一艘船。','The dates in the shipping log showed a close correspondence with the harbor records / allowing the archivist / to match each delivery to a vessel.','correspondence between/with 表示两组信息相符；allowing 引出匹配结果。','两个档案日期一致并可相互对应，符合 s2。')],mistakes:[M('The two sets of measurements showed correspondence, although one consistently increased whenever the other decreased and their values never matched.','The two sets of measurements showed an inverse relationship rather than correspondence, because their values moved in opposite directions and did not match.','数值方向相反且不匹配，不能据此称为相符。')],quiz:[Q('correspondence',1,2,'Correspondence between two records means?',['a matching or agreement between them','a parcel delivered by conveyor','a formal meeting called by a chair'],'a matching or agreement between them','The sense concerns agreement between things.'),Q('correspondence',2,1,'A folder of correspondence contains?',['letters or messages exchanged','only shipping crates','a flower’s petals'],'letters or messages exchanged','Correspondence can mean a collection of letters.'),Q('correspondence',3,1,'Which item is correspondence?',['emails exchanged between a researcher and an editor','a single unsigned blank form','a brass musical instrument'],'emails exchanged between a researcher and an editor','Messages exchanged between people are correspondence.'),Q('correspondence',4,1,'Choose the natural phrase.',['in correspondence with the agency','in correspondence at the agency','a correspondence to the agency on Tuesday only'],'in correspondence with the agency','The usual expression is be in correspondence with someone.') ]});
D('correspondent',{etymology:E('Correspondent derives from correspond, ultimately Latin correspondere “answer or agree,” plus agent suffix -ent; it names a journalist or a person who exchanges letters.','correspondent'),contexts:[C('correspondent.s1','海外报道','The correspondent filed a report from the border crossing, describing the queue and verifying the official’s account with two independent witnesses.','通讯记者从边境口岸发回报道，描述排队情况，并用两名独立证人的说法核实官员的陈述。','The correspondent filed a report from the border crossing / describing the queue / and verifying the official’s account / with two independent witnesses.','correspondent 作记者义；from 引出处，verifying 说明核实报道内容。','记者在现场发回消息并核实信息，符合新闻通讯员义 s1。')],mistakes:[M('The newspaper sent a correspondent to report from the flood zone, but described the person as someone who never writes or sends reports.','The newspaper sent a correspondent to report from the flood zone, describing the person as a journalist who sends reports.','被派去发回报道的人正是新闻 correspondent。')],quiz:[Q('correspondent',1,1,'A foreign correspondent is?',['a journalist reporting from another country','a person who repairs wooden casks','a patient recovering at home'],'a journalist reporting from another country','A correspondent is a journalist who reports from a location.'),Q('correspondent',2,2,'Two correspondents may be?',['people who write letters to each other','people who never communicate','two matching legal deeds'],'people who write letters to each other','The noun also means someone who exchanges letters.'),Q('correspondent',3,1,'Which task suits a correspondent?',['sending verified news from a distant city','tending the corolla of a flower','building a cooling system'],'sending verified news from a distant city','A journalist correspondent reports from a location.'),Q('correspondent',4,1,'In “my regular correspondent,” the person likely?',['exchanges letters or messages with me','delivers my parcels by conveyor','owns the newspaper office'],'exchanges letters or messages with me','Correspondent can refer to a letter-writing contact.') ]});
D('correspondingly',{etymology:E('Correspondingly is corresponding plus -ly; correspond derives from Latin correspondere, “answer or agree,” and the adverb marks a matching change or relation.','correspondingly'),contexts:[C('correspondingly.s1','预算调整','The project’s fuel budget fell by 12 percent, and the transport allocation was reduced correspondingly so the total plan stayed within its limit.','项目燃料预算下降了12%，交通经费也相应削减，使总预算保持在限额以内。','The project’s fuel budget fell by 12 percent / and the transport allocation was reduced correspondingly / so the total plan stayed within its limit.','correspondingly 修饰 reduced，表示调整与前述变化相匹配。','第二项经费随第一项预算变化而相应调整。')],mistakes:[M('The water level doubled, and the gauge reading fell correspondingly by half despite the gauge measuring the same water.','The water level doubled, and the gauge reading rose correspondingly if the gauge tracked that level.','若仪表随水位变化，读数应匹配上升而非反向减半。','usage')],quiz:[Q('correspondingly',1,1,'If one cost drops and another is adjusted correspondingly, the second cost changes?',['in a matching way','without any relation to the first','only after a century'],'in a matching way','The adverb signals a corresponding or matching change.'),Q('correspondingly',2,1,'“The room grew quieter; correspondingly, the speaker lowered her voice.” The adverb links?',['a related adjustment','an unrelated coincidence','a spelling correction'],'a related adjustment','The voice change matches the quieter room.'),Q('correspondingly',3,1,'Which sentence uses correspondingly?',['Demand rose, and production increased correspondingly.','Demand rose, and production stayed unrelated correspondingly.','She correspondingly the production yesterday.'],'Demand rose, and production increased correspondingly.','Production changes in response to demand.'),Q('correspondingly',4,1,'A correspondingly larger fee is one that is?',['larger in a matching relation to another increase','exactly the same as before','smaller for no stated reason'],'larger in a matching relation to another increase','The adverbial idea is proportional or matching adjustment.') ]});
D('corroborate',{etymology:E('Corroborate came from Latin corroborare “strengthen,” from cor- “together” and roborare “make strong,” related to robur “strength”; it means support with confirming evidence.','corroborate'),contexts:[C('corroborate.s1','事故调查','A second camera angle corroborated the driver’s account: it showed the traffic light turning green several seconds before the car entered the junction.','第二个摄像机角度证实了司机的说法：画面显示汽车进入路口前几秒信号灯已转绿。','A second camera angle corroborated the driver’s account / it showed the traffic light turning green / several seconds before the car entered the junction.','corroborate an account 表示用额外证据支持/印证；冒号给出证据内容。','独立影像提供吻合证据，支持司机的说法。')],mistakes:[M('The witness corroborated the allegation by presenting records that disproved it and confirmed the opposite timeline.','The witness controverted the allegation by presenting records that disproved it and confirmed the opposite timeline.','反证驳斥 allegation 应为 controvert；corroborate 表示支持。','confusable')],quiz:[Q('corroborate',1,1,'To corroborate a witness’s story is to?',['support it with confirming evidence','argue that it is false','erase the witness’s memory'],'support it with confirming evidence','Corroborate means to provide evidence that supports a claim.'),Q('corroborate',2,1,'Which item could corroborate a travel alibi?',['a time-stamped ticket matching the stated trip','a record showing the person was elsewhere','an unrelated recipe'],'a time-stamped ticket matching the stated trip','The ticket independently supports the account.'),Q('corroborate',3,1,'A second study corroborates a finding when it?',['produces evidence consistent with that finding','contradicts every reported result','uses the same title but no data'],'produces evidence consistent with that finding','Agreement from further evidence strengthens the conclusion.'),Q('corroborate',4,1,'Choose the best completion: “The logs corroborate ___.”',['the technician’s account','the act of disproving it','a flower’s root system'],'the technician’s account','Records can support a person’s account.') ]});
D('corse',{etymology:E('Corse is an archaic English form descended through Old French cors from Latin corpus “body”; in older literary usage it means a dead body or corpse.','corse'),contexts:[C('corse.s1','古典诗歌','The medieval poem calls the fallen knight’s body a corse, an archaic spelling that tells modern readers the passage belongs to an older literary register.','这首中世纪诗歌把倒下骑士的尸体称作 corse；这种古旧拼法提示现代读者该段属于较早的文学语域。','The medieval poem calls the fallen knight’s body a corse / an archaic spelling / that tells modern readers / the passage belongs to an older literary register.','corse 是 corpse 的古语形式；同位语补充其拼写与语域。','上下文明确是古诗中死者的身体，符合古语义。')],mistakes:[M('The corse sat up, asked for water, and walked out of the hospital while the narrator insisted it was an ordinary dead body.','The patient sat up, asked for water, and walked out of the hospital.','corse 指尸体；能坐起交谈离开的活人不能称为尸体。','word-choice')],quiz:[Q('corse',1,1,'In older literary English, a corse is?',['a corpse or dead body','a living patient asking for water','a flower’s outer atmosphere'],'a corpse or dead body','Corse is an archaic form of corpse.'),Q('corse',2,1,'Where is corse most likely to appear?',['in an old poem or historical passage','in everyday modern conversation as a common word','on a car coolant label'],'in an old poem or historical passage','The word is archaic and literary.'),Q('corse',3,1,'The knight’s corse lay on the field. The knight was?',['dead','recovering from a mild cold','reporting for a newspaper'],'dead','Corse refers to a dead body.'),Q('corse',4,1,'Which modern word is closest in meaning?',['corpse','copilot','corolla'],'corpse','Corpse is the modern standard form.') ]});
D('corselet',{etymology:E('Corselet came through French corselet, a diminutive of cors “body”; it names torso armor and, in some use, a close-fitting garment for the trunk.','corselet'),contexts:[C('corselet.s1','博物馆展览','The curator displayed a bronze corselet beside the helmet, explaining that the fitted armor protected the wearer’s chest and abdomen.','策展人在头盔旁展出一件青铜胸甲，并说明贴身护甲保护穿戴者的胸部和腹部。','The curator displayed a bronze corselet beside the helmet / explaining that the fitted armor / protected the wearer’s chest and abdomen.','corselet 修饰 bronze，作 torso armor；that 从句说明防护部位。','胸腹护甲与头盔并列展出，符合护甲义 s1。')],mistakes:[M('The museum label says the soldier corseleted his torso before battle.','The museum label says the soldier put on a corselet to protect his torso before battle.','corselet 是名词，不能按此义直接作动词；应说 put on a corselet。','word form')],quiz:[Q('corselet',1,1,'A medieval corselet protects mainly the?',['torso','feet only','head alone'],'torso','The armor covers the trunk of the body.'),Q('corselet',2,1,'A curator places a corselet next to a helmet because it is?',['armor worn over the chest and body','a flower petal','a kind of barrel'],'armor worn over the chest and body','The historical armor sense covers the torso.'),Q('corselet',3,1,'Which sentence uses corselet as a noun?',['The soldier wore a corselet beneath his cloak.','The soldier corseleted beneath his cloak.','The corselet the soldier carefully.'],'The soldier wore a corselet beneath his cloak.','The word names the fitted torso armor or garment.'),Q('corselet',4,1,'The French source relates corselet to a word meaning?',['body','crown','sea raven'],'body','The French base cors means body.') ]});
D('corset',{etymology:E('Corset came from French corset, a diminutive of cors “body”; it names a close-fitting support garment traditionally laced to shape or support the waist and trunk.','corset'),contexts:[C('corset.s1','服装史','The exhibition displayed a nineteenth-century corset beside a modern support garment, noting that the older design was tightly laced around the waist.','展览在现代支撑衣旁展示了一件十九世纪束身衣，并指出旧式设计会在腰部紧紧系带。','The exhibition displayed a nineteenth-century corset / beside a modern support garment / noting that the older design / was tightly laced around the waist.','corset 是束身/支撑衣物；过去分词 laced 描述传统系带方式。','贴身并在腰部系紧的衣物体现词义。')],mistakes:[M('She wore a corset as footwear, tying it over her boots to keep her feet warm.','She wore a corset around her torso, tying it at the waist for support.','corset 穿在躯干而非脚上；靴子才是脚部穿戴物。','word-choice')],quiz:[Q('corset',1,1,'A corset is worn around the?',['waist and trunk','feet as a shoe','head as a helmet'],'waist and trunk','The garment fits closely around the torso.'),Q('corset',2,1,'Historically, a corset might be?',['laced tightly to shape or support the waist','used to transport cattle','a device for cooling an engine'],'laced tightly to shape or support the waist','Traditional corsets often used laces for a close fit.'),Q('corset',3,1,'Which item is a corset?',['a fitted garment worn on the torso','a barrel made by a cooper','a solar telescope'],'a fitted garment worn on the torso','The noun refers to a close-fitting body garment.'),Q('corset',4,1,'A modern support corset might help?',['support the trunk','polish copper sheets','carry packages on a belt'],'support the trunk','Corsets can be worn as support garments.') ]});
D('cortex',{etymology:E('Cortex is a Latin loan meaning “bark”; anatomists and botanists use it for the outer layer of an organ, root, or stem.','cortex'),contexts:[C('cortex.s1','脑部解剖','The scan showed a small lesion near the cerebral cortex, the brain’s outer layer where many functions involving sensation and thought are processed.','扫描显示大脑皮层附近有一处小病灶；皮层是大脑外层，许多与感觉和思维有关的功能在此处理。','The scan showed a small lesion near the cerebral cortex / the brain’s outer layer / where many functions involving sensation and thought are processed.','cortex 后的同位语解释它是 brain 的外层；where 引导地点关系从句。','语境指脑的外层组织，符合词条义。')],mistakes:[M('The brain’s cortex is its deepest central cavity, entirely surrounded by outer tissue.','The brain’s cortex is its outer layer, surrounding deeper structures.','cortex 指器官外层；最深处的腔体与定义相反。','confusable')],quiz:[Q('cortex',1,1,'The cerebral cortex is located?',['on the brain’s outer layer','inside a chicken coop','at the center of a steel barrel'],'on the brain’s outer layer','Cortex names an organ’s outer layer.'),Q('cortex',2,1,'A plant root cortex is?',['tissue forming an outer region of the root','a flower’s sound','a legal contract'],'tissue forming an outer region of the root','The word applies to outer layers in plants as well.'),Q('cortex',3,1,'Which phrase uses cortex correctly?',['the cortex of the kidney','the cortex of a newspaper article’s punctuation','the cortex of a conveyor belt’s speed'],'the cortex of the kidney','Organs such as the kidney have a cortex, an outer layer.'),Q('cortex',4,1,'The Latin source of cortex meant?',['bark','to call a meeting','to transfer ownership'],'bark','The anatomical term is borrowed from Latin for bark.') ]});
D('cortical',{etymology:E('Cortical is cortex plus the adjectival suffix -al; it means relating to an outer layer such as the cortex of the brain, kidney, or a plant.','cortical'),contexts:[C('cortical.s1','神经科学','The cortical scan revealed activity near the visual area while the volunteer identified shapes shown briefly on a screen.','皮层扫描显示，志愿者辨认屏幕上短暂呈现的形状时，视觉区域附近出现了活动。','The cortical scan revealed activity near the visual area / while the volunteer identified shapes / shown briefly on a screen.','cortical 修饰 scan，指与大脑皮层有关；while 表示扫描期间进行的任务。','视觉皮层附近的活动属于大脑皮层相关现象。')],mistakes:[M('A cortical response comes from the cortex, the brain’s outer layer, but the report defines cortical as relating only to the stomach.','A gastric response relates to the stomach; a cortical response relates to the cortex.','cortical 指皮层，不是胃；胃相关可用 gastric。','confusable')],quiz:[Q('cortical',1,1,'Cortical activity is activity related to the?',['cortex','corolla','corral'],'cortex','Cortical is the adjective form of cortex.'),Q('cortical',2,1,'A cortical scan of the brain focuses on?',['its outer layer','the liver’s bile duct','a flower’s petals'],'its outer layer','The cerebral cortex is the brain’s outer layer.'),Q('cortical',3,1,'Which phrase is correctly formed?',['cortical tissue','cortically tissue','a cortexal scan'],'cortical tissue','The standard adjective is cortical.'),Q('cortical',4,1,'A cortical plant layer would be associated with?',['the outer tissue of a root or stem','the feathers of a cormorant','the wheels of a conveyor'],'the outer tissue of a root or stem','The term also applies to cortex in plant roots and stems.') ]});
D('cosmic',{etymology:E('Cosmic came from Greek kosmikos, from kosmos “order, world, universe”; it means relating to the universe and is also an informal exaggeration for something enormous.','cosmic'),contexts:[C('cosmic.s2','日常夸张','The repair bill was cosmic by the family’s standards: replacing the flooded basement pump cost nearly as much as their used car.','按这家人的标准，维修账单简直大得惊人：更换被水淹坏的地下室水泵，花费几乎赶上一辆二手车。','The repair bill was cosmic by the family’s standards / replacing the flooded basement pump / cost nearly as much as their used car.','cosmic 作口语夸张义，表示大得惊人；冒号解释为何觉得费用极高。','与二手车价格相当的维修费被夸张称作 cosmic，符合 s2。')],mistakes:[M('The astronomer described a planet orbiting a star as a cosmic object but claimed cosmic can only mean “very tasty.”','The astronomer described a planet orbiting a star as a cosmic object, using cosmic in its universe-related sense.','天体属于宇宙相关的 cosmic；该词不表示“美味”。','meaning')],quiz:[Q('cosmic',1,1,'Cosmic radiation comes from?',['space or the universe','a neighborhood cookout','a barrel workshop'],'space or the universe','The main sense is relating to the universe.'),Q('cosmic',2,2,'In informal speech, a cosmic bill may be?',['extremely large','a tiny sum of one cent','a document about a corolla'],'extremely large','Cosmic can be used humorously or informally to mean enormous.'),Q('cosmic',3,1,'Which phrase uses the scientific sense?',['cosmic background radiation','cosmic paperwork meaning unusually delicious','cosmic shoe leather'],'cosmic background radiation','The phrase concerns radiation from the universe.'),Q('cosmic',4,1,'A cosmic event is most likely?',['one on a universe-wide scale','a small office filing task','the repair of a single shoelace'],'one on a universe-wide scale','The adjective relates to the cosmos.') ]});
D('cosmography',{etymology:E('Cosmography is formed from Greek kosmos “world, universe” and graphein “write or describe”; the historical discipline describes or maps the heavens and Earth as a whole.','cosmography'),contexts:[C('cosmography.s1','科学史','The museum’s cosmography exhibit showed how early scholars mapped the Earth and the heavens together before modern astronomy separated many specialized fields.','博物馆的宇宙志展览展示了早期学者如何把地球与天体一并绘制成图，而现代天文学后来把许多专门领域分开。','The museum’s cosmography exhibit showed / how early scholars mapped the Earth and the heavens together / before modern astronomy separated / many specialized fields.','cosmography 指描述或绘制天地总体结构的学科；how 引导展览所呈现的内容。','将地球与天体合在一起描绘，符合历史宇宙志义。')],mistakes:[M('The old cosmography was a recipe collection listing spices and baking times, with no map or description of the world.','The old cookbook was a recipe collection listing spices and baking times, with no map or description of the world.','不涉及天地描绘的菜谱集不是 cosmography。','word-choice')],quiz:[Q('cosmography',1,1,'Cosmography traditionally describes or maps?',['the Earth and the heavens as a whole','only a person’s letters','the cost of a company’s fuel'],'the Earth and the heavens as a whole','The discipline describes the cosmos and its arrangement.'),Q('cosmography',2,1,'Which project is cosmography?',['drawing a map that locates Earth within the heavens','counting petals on one flower only','repairing a wooden barrel'],'drawing a map that locates Earth within the heavens','Cosmography concerns the description and mapping of the world and heavens.'),Q('cosmography',3,1,'The element cosmo- refers to?',['the world or universe','a small room','a person who writes letters'],'the world or universe','The first element comes from Greek kosmos.'),Q('cosmography',4,1,'A historical cosmographer would be interested in?',['how people represented the structure of Earth and sky','how to tighten a corset','how a corral is fenced'],'how people represented the structure of Earth and sky','Cosmography is a description or map of the heavens and Earth.') ]});
D('cosmology',{etymology:E('Cosmology combines Greek kosmos “world, universe” with -logy, from logos “study or account”; it is the scientific or philosophical study of the universe’s origin, structure, and development.','cosmology'),contexts:[C('cosmology.s1','宇宙学讲座','The cosmology seminar compared models of how the universe expanded, asking which observations could distinguish a rapid early expansion from slower alternatives.','宇宙学研讨会比较了宇宙如何膨胀的模型，并探讨哪些观测能区分快速早期膨胀与较慢的其他模型。','The cosmology seminar compared models of how the universe expanded / asking which observations / could distinguish a rapid early expansion / from slower alternatives.','cosmology 修饰 seminar，指研究宇宙起源、结构与演化的领域。','讨论宇宙膨胀模型及可检验观测，属于宇宙学。')],mistakes:[M('Cosmology studies the universe’s origin and evolution, but the course description says it concerns only how to bake pastries.','The cosmology course studies the universe’s origin and evolution, not pastry preparation.','宇宙学研究宇宙，不研究烘焙；后者属于 cookery。','confusable')],quiz:[Q('cosmology',1,1,'Cosmology studies?',['the origin, structure, and evolution of the universe','the methods of making wooden casks','the arrangement of flower petals'],'the origin, structure, and evolution of the universe','Cosmology is the science or philosophy of the universe.'),Q('cosmology',2,1,'A cosmologist might investigate?',['evidence about the universe’s early expansion','the best way to grill vegetables','how to repair a corset'],'evidence about the universe’s early expansion','Early expansion is a central cosmological question.'),Q('cosmology',3,1,'The suffix -logy generally means?',['study or account of a subject','a person who makes shoes','an outdoor meal'],'study or account of a subject','Cosmology is the study of the cosmos.'),Q('cosmology',4,1,'Which question belongs to cosmology?',['How did the universe develop?','How many petals form this flower’s corolla?','Who repaired the barrel?'],'How did the universe develop?','Cosmology addresses the universe’s history and structure.') ]});
D('cosset',{etymology:E('Cosset is an old English verb for pampering or treating with excessive care; its deeper origin is uncertain. The related noun can mean a pet lamb or other favored young animal.','cosset'),contexts:[C('cosset.s1','家庭照料','The family cosseted the elderly dog during recovery, carrying its water bowl close by and giving it quiet rest without letting it climb the stairs.','老狗康复期间，全家对它呵护备至，把水碗放在近处，安排安静休息，也不让它爬楼梯。','The family cosseted the elderly dog during recovery / carrying its water bowl close by / and giving it quiet rest / without letting it climb the stairs.','cosset 是及物动词，表示过分照顾/呵护；carrying 和 giving 列举具体方式。','照料周到到近乎溺爱，符合动词义。')],mistakes:[M('The family cosseted the recovering dog by abandoning it outdoors without food, shelter, or attention.','The family neglected the recovering dog by abandoning it outdoors without food, shelter, or attention.','弃置不管是 neglect，与 cosset（细心呵护、溺爱）含义相反。','confusable')],quiz:[Q('cosset',1,1,'To cosset a child is to?',['pamper the child with excessive care','leave the child entirely without care','summon the child to a formal assembly'],'pamper the child with excessive care','Cosset means to treat someone with excessive care and comfort.'),Q('cosset',2,2,'A cosset kept on a farm may be?',['a favored pet lamb','a steel converter','a newspaper correspondent'],'a favored pet lamb','The noun can refer to a pet lamb or other cherished young animal.'),Q('cosset',3,1,'Which action best illustrates cosset?',['bringing a recovering pet its food and arranging extra comfort','ignoring the pet for several days','sending the pet to report from abroad'],'bringing a recovering pet its food and arranging extra comfort','The careful, indulgent treatment fits the verb.'),Q('cosset',4,1,'Choose the contrast.',['cosset: pamper; neglect: fail to care for','cosset: dispute; neglect: corroborate','both words mean transport'],'cosset: pamper; neglect: fail to care for','The words have opposing meanings about care.') ]});
D('cost-effective',{etymology:E('Cost-effective is a modern compound of cost and effective; it describes an approach that produces useful results in relation to the money spent, not necessarily the cheapest option.','cost-effective'),contexts:[C('cost-effective.s1','公共卫生预算','The vaccination program proved cost-effective because its upfront expense prevented many hospital admissions and reduced the much larger treatment bill.','疫苗接种项目被证明具有成本效益，因为前期投入避免了许多住院病例，并减少了高得多的治疗费用。','The vaccination program proved cost-effective / because its upfront expense prevented many hospital admissions / and reduced the much larger treatment bill.','cost-effective 作表语，评价结果与成本的关系；because 从句说明节省机制。','前期花费带来更大医疗节省，体现有成本效益。')],mistakes:[M('The plan was cost-effective even though it cost ten times more, produced no additional benefit, and saved no future expense.','The plan was not cost-effective: it cost ten times more, produced no additional benefit, and saved no future expense.','成本远高且无额外收益或节省，不能称 cost-effective。','word-choice')],quiz:[Q('cost-effective',1,1,'A cost-effective solution?',['delivers useful results for the money spent','must always have the lowest initial price','uses money without producing any benefit'],'delivers useful results for the money spent','Cost-effectiveness compares useful outcomes with the resources spent.'),Q('cost-effective',2,1,'A more expensive treatment can still be cost-effective if it?',['prevents far greater future costs','produces no added benefit','wastes more money for the same result'],'prevents far greater future costs','Higher upfront cost may be justified by larger savings or outcomes.'),Q('cost-effective',3,1,'Which purchase is most likely cost-effective?',['a durable pump that costs more but lasts five times longer','a costly pump that breaks immediately and cannot be repaired','the cheapest tool that cannot do the required job'],'a durable pump that costs more but lasts five times longer','Longer useful life can make the total value better.'),Q('cost-effective',4,1,'A cost-effective public program is judged by?',['its results relative to its cost','its spelling and punctuation','whether it is delivered outdoors'],'its results relative to its cost','The compound assesses effectiveness in relation to expense.') ]});

})();
